-- =====================================================================
-- SIGCA-EPQ  ·  Modelo de datos Oracle  ·  01_tablas.sql
-- Tablas, claves primarias/foráneas, UNIQUE, CHECK y NOT NULL.
-- Compatible con Oracle 19c, 21c y 23ai. Ejecutar como el esquema dueño (SIGCA).
--
-- Convenciones
--   * PK:  ID NUMBER(19) GENERATED ALWAYS AS IDENTITY (P-01). En JPA:
--          @GeneratedValue(strategy = GenerationType.IDENTITY). La base de datos
--          rechaza un ID enviado por el cliente.
--   * Booleanos: CHAR(1) 'S' / 'N'.
--   * Periodos de facturación: NUMBER(6) con formato AAAAMM.
--   * Dinero: NUMBER(14,2) en pesos colombianos. Consumos: NUMBER(12,3) en m³.
--   * Columnas de auditoría técnica: CREADO_EN, CREADO_POR, ACTUALIZADO_EN,
--     ACTUALIZADO_POR y VERSION (bloqueo optimista JPA @Version).
--   * Restricciones DEFERRABLE INITIALLY DEFERRED: se verifican al COMMIT
--     (factura con líneas, acuerdo con facturas y cuotas completas).
-- =====================================================================

-- Consecutivos de negocio (códigos legibles). Incremento 1; pueden quedar huecos
-- por rollback, por eso no se usan como numeración fiscal (esa la asigna el ERP).
CREATE SEQUENCE SEQ_COD_USUARIO   START WITH 1 INCREMENT BY 1 CACHE 20;
CREATE SEQUENCE SEQ_COD_PREDIO    START WITH 1 INCREMENT BY 1 CACHE 20;
CREATE SEQUENCE SEQ_COD_CONTRATO  START WITH 1 INCREMENT BY 1 CACHE 20;
CREATE SEQUENCE SEQ_COD_FACTURA   START WITH 1 INCREMENT BY 1 CACHE 100;
CREATE SEQUENCE SEQ_COD_PAGO      START WITH 1 INCREMENT BY 1 CACHE 20;
CREATE SEQUENCE SEQ_COD_ACUERDO   START WITH 1 INCREMENT BY 1 CACHE 20;
CREATE SEQUENCE SEQ_COD_ORDEN     START WITH 1 INCREMENT BY 1 CACHE 20;

-- =====================================================================
-- 1. CATÁLOGOS Y PARÁMETROS
-- =====================================================================

-- Municipios donde opera EPQ (P-02: 9 municipios; CO-03 valida MunicipioNoAtendidoException)
CREATE TABLE MUNICIPIO (
    ID              NUMBER(19)        GENERATED ALWAYS AS IDENTITY,
    CODIGO_DANE     VARCHAR2(5 CHAR)  NOT NULL,
    NOMBRE          VARCHAR2(60 CHAR) NOT NULL,
    ACTIVO          CHAR(1)           DEFAULT 'S' NOT NULL,
    CONSTRAINT PK_MUNICIPIO PRIMARY KEY (ID),
    CONSTRAINT UK_MUNICIPIO_DANE UNIQUE (CODIGO_DANE),
    CONSTRAINT UK_MUNICIPIO_NOMBRE UNIQUE (NOMBRE),
    CONSTRAINT CK_MUNICIPIO_DANE CHECK (REGEXP_LIKE(CODIGO_DANE, '^63[0-9]{3}$')),
    CONSTRAINT CK_MUNICIPIO_ACTIVO CHECK (ACTIVO IN ('S','N'))
);

-- Sectores atendidos dentro de un municipio (P-02): zona rural de Buenavista,
-- corregimiento Pueblo Tapao (Montenegro). El predio lo referencia de forma opcional.
CREATE TABLE SECTOR (
    ID              NUMBER(19)         GENERATED ALWAYS AS IDENTITY,
    MUNICIPIO_ID    NUMBER(19)         NOT NULL,
    NOMBRE          VARCHAR2(80 CHAR)  NOT NULL,
    TIPO            VARCHAR2(15 CHAR)  NOT NULL,
    ACTIVO          CHAR(1)            DEFAULT 'S' NOT NULL,
    CONSTRAINT PK_SECTOR PRIMARY KEY (ID),
    CONSTRAINT UK_SECTOR_NOMBRE UNIQUE (MUNICIPIO_ID, NOMBRE),
    -- Clave candidata para que PREDIO garantice que el sector es de su municipio
    CONSTRAINT UK_SECTOR_MUNICIPIO UNIQUE (ID, MUNICIPIO_ID),
    CONSTRAINT FK_SECTOR_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    CONSTRAINT CK_SECTOR_NOMBRE CHECK (LENGTH(TRIM(NOMBRE)) >= 3),
    CONSTRAINT CK_SECTOR_TIPO CHECK (TIPO IN ('ZONA_RURAL','CORREGIMIENTO','VEREDA','URBANO')),
    CONSTRAINT CK_SECTOR_ACTIVO CHECK (ACTIVO IN ('S','N'))
);

-- Festivos nacionales: base para calcular días hábiles (RN-04, CO-01, P-09)
CREATE TABLE FESTIVO (
    FECHA        DATE               NOT NULL,
    DESCRIPCION  VARCHAR2(100 CHAR) NOT NULL,
    CONSTRAINT PK_FESTIVO PRIMARY KEY (FECHA),
    CONSTRAINT CK_FESTIVO_SIN_HORA CHECK (FECHA = TRUNC(FECHA))
);

-- Parámetros configurables por el Administrador (RF-29). Los rangos legales
-- entre parámetros los valida el trigger TRG_PARAMETRO_CIU.
CREATE TABLE PARAMETRO_SISTEMA (
    CLAVE            VARCHAR2(60 CHAR)  NOT NULL,
    VALOR            VARCHAR2(400 CHAR) NOT NULL,
    TIPO_DATO        VARCHAR2(10 CHAR)  NOT NULL,
    DESCRIPCION      VARCHAR2(300 CHAR) NOT NULL,
    ACTUALIZADO_EN   TIMESTAMP          DEFAULT SYSTIMESTAMP NOT NULL,
    ACTUALIZADO_POR  VARCHAR2(100 CHAR) DEFAULT 'SISTEMA' NOT NULL,
    CONSTRAINT PK_PARAMETRO_SISTEMA PRIMARY KEY (CLAVE),
    CONSTRAINT CK_PARAMETRO_CLAVE CHECK (REGEXP_LIKE(CLAVE, '^[A-Z][A-Z0-9_]*$')),
    CONSTRAINT CK_PARAMETRO_TIPO CHECK (TIPO_DATO IN ('ENTERO','DECIMAL','TEXTO','BOOLEANO')),
    CONSTRAINT CK_PARAMETRO_ENTERO CHECK (TIPO_DATO <> 'ENTERO' OR REGEXP_LIKE(VALOR, '^-?[0-9]+$')),
    CONSTRAINT CK_PARAMETRO_DECIMAL CHECK (TIPO_DATO <> 'DECIMAL' OR REGEXP_LIKE(VALOR, '^-?[0-9]+(\.[0-9]+)?$')),
    CONSTRAINT CK_PARAMETRO_BOOLEANO CHECK (TIPO_DATO <> 'BOOLEANO' OR VALOR IN ('S','N')),
    -- P-11 / Ley 142 art. 140: con facturación mensual la suspensión no puede exigir más de 3 periodos
    CONSTRAINT CK_PARAMETRO_MORA_PERIODOS CHECK (CLAVE <> 'MORA_PERIODOS_SUSPENSION' OR VALOR IN ('1','2','3'))
);

-- =====================================================================
-- 2. SEGURIDAD: FUNCIONARIOS Y RBAC (RF-14, RNF-05, P-16, P-20)
-- =====================================================================

CREATE TABLE ROL (
    ID           NUMBER(19)         GENERATED ALWAYS AS IDENTITY,
    CODIGO       VARCHAR2(30 CHAR)  NOT NULL,
    NOMBRE       VARCHAR2(80 CHAR)  NOT NULL,
    DESCRIPCION  VARCHAR2(300 CHAR),
    ACTIVO       CHAR(1)            DEFAULT 'S' NOT NULL,
    CONSTRAINT PK_ROL PRIMARY KEY (ID),
    CONSTRAINT UK_ROL_CODIGO UNIQUE (CODIGO),
    CONSTRAINT CK_ROL_CODIGO CHECK (REGEXP_LIKE(CODIGO, '^[A-Z][A-Z0-9_]*$')),
    CONSTRAINT CK_ROL_ACTIVO CHECK (ACTIVO IN ('S','N'))
);

CREATE TABLE PERMISO (
    ID           NUMBER(19)         GENERATED ALWAYS AS IDENTITY,
    CODIGO       VARCHAR2(60 CHAR)  NOT NULL,
    MODULO       VARCHAR2(30 CHAR)  NOT NULL,
    DESCRIPCION  VARCHAR2(300 CHAR) NOT NULL,
    CONSTRAINT PK_PERMISO PRIMARY KEY (ID),
    CONSTRAINT UK_PERMISO_CODIGO UNIQUE (CODIGO),
    CONSTRAINT CK_PERMISO_CODIGO CHECK (REGEXP_LIKE(CODIGO, '^[A-Z][A-Z0-9_]*$')),
    CONSTRAINT CK_PERMISO_MODULO CHECK (MODULO IN
        ('PORTAL','USUARIOS','CONTRATOS','LECTURAS','FACTURACION','PAGOS','CARTERA','PQR','REPORTES','ADMINISTRACION'))
);

CREATE TABLE ROL_PERMISO (
    ROL_ID      NUMBER(19) NOT NULL,
    PERMISO_ID  NUMBER(19) NOT NULL,
    CONSTRAINT PK_ROL_PERMISO PRIMARY KEY (ROL_ID, PERMISO_ID),
    CONSTRAINT FK_ROLPER_ROL FOREIGN KEY (ROL_ID) REFERENCES ROL (ID) ON DELETE CASCADE,
    CONSTRAINT FK_ROLPER_PERMISO FOREIGN KEY (PERMISO_ID) REFERENCES PERMISO (ID) ON DELETE CASCADE
);

-- Funcionario de EPQ (dominio: FuncionarioEPQ). JWT + 2FA TOTP obligatorio (P-20):
-- el primer ingreso exige enrolar el segundo factor antes de registrar ULTIMO_ACCESO.
CREATE TABLE FUNCIONARIO (
    ID                     NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    CODIGO_FUNCIONARIO     VARCHAR2(20 CHAR)   NOT NULL,
    NOMBRE_COMPLETO        VARCHAR2(150 CHAR)  NOT NULL,
    CORREO                 VARCHAR2(254 CHAR)  NOT NULL,
    TELEFONO               VARCHAR2(13 CHAR),
    USERNAME               VARCHAR2(60 CHAR)   NOT NULL,
    PASSWORD_HASH          VARCHAR2(255 CHAR)  NOT NULL,
    CAMBIO_PASSWORD_REQUERIDO CHAR(1)          DEFAULT 'S' NOT NULL,
    DOBLE_FACTOR_ACTIVO    CHAR(1)             DEFAULT 'N' NOT NULL,
    SECRETO_DOBLE_FACTOR   VARCHAR2(255 CHAR),
    INTENTOS_FALLIDOS      NUMBER(2)           DEFAULT 0 NOT NULL,
    BLOQUEADO_HASTA        TIMESTAMP,
    ULTIMO_ACCESO          TIMESTAMP,
    MUNICIPIO_ID           NUMBER(19),
    ACTIVO                 CHAR(1)             DEFAULT 'S' NOT NULL,
    FECHA_DESACTIVACION    TIMESTAMP,
    CREADO_EN              TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR             VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN         TIMESTAMP,
    ACTUALIZADO_POR        VARCHAR2(100 CHAR),
    VERSION                NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_FUNCIONARIO PRIMARY KEY (ID),
    CONSTRAINT UK_FUNC_CODIGO UNIQUE (CODIGO_FUNCIONARIO),
    CONSTRAINT UK_FUNC_CORREO UNIQUE (CORREO),
    CONSTRAINT UK_FUNC_USERNAME UNIQUE (USERNAME),
    CONSTRAINT FK_FUNC_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    CONSTRAINT CK_FUNC_CODIGO CHECK (REGEXP_LIKE(CODIGO_FUNCIONARIO, '^[A-Z0-9-]{3,20}$')),
    CONSTRAINT CK_FUNC_NOMBRE CHECK (REGEXP_LIKE(TRIM(NOMBRE_COMPLETO), '^[[:alpha:]][[:alpha:] .''-]{2,149}$')),
    CONSTRAINT CK_FUNC_CORREO CHECK (
        CORREO = LOWER(TRIM(CORREO)) AND REGEXP_LIKE(CORREO, '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$')),
    CONSTRAINT CK_FUNC_TELEFONO CHECK (TELEFONO IS NULL OR REGEXP_LIKE(TELEFONO, '^(\+57)?(3[0-9]{9}|60[0-9]{8})$')),
    CONSTRAINT CK_FUNC_USERNAME CHECK (REGEXP_LIKE(USERNAME, '^[a-z0-9._-]{3,60}$')),
    CONSTRAINT CK_FUNC_PASSWORD CHECK (LENGTH(PASSWORD_HASH) >= 60),
    CONSTRAINT CK_FUNC_CAMBIO_PWD CHECK (CAMBIO_PASSWORD_REQUERIDO IN ('S','N')),
    CONSTRAINT CK_FUNC_2FA CHECK (
        (DOBLE_FACTOR_ACTIVO = 'S' AND SECRETO_DOBLE_FACTOR IS NOT NULL) OR DOBLE_FACTOR_ACTIVO = 'N'),
    -- P-20: ningún funcionario completa un inicio de sesión sin segundo factor
    CONSTRAINT CK_FUNC_2FA_OBLIGATORIO CHECK (ULTIMO_ACCESO IS NULL OR DOBLE_FACTOR_ACTIVO = 'S'),
    CONSTRAINT CK_FUNC_INTENTOS CHECK (INTENTOS_FALLIDOS BETWEEN 0 AND 99),
    CONSTRAINT CK_FUNC_ACTIVO CHECK (ACTIVO IN ('S','N')),
    CONSTRAINT CK_FUNC_DESACTIVACION CHECK (
        (ACTIVO = 'S' AND FECHA_DESACTIVACION IS NULL) OR (ACTIVO = 'N' AND FECHA_DESACTIVACION IS NOT NULL)),
    CONSTRAINT CK_FUNC_VERSION CHECK (VERSION >= 0)
);

CREATE TABLE FUNCIONARIO_ROL (
    FUNCIONARIO_ID    NUMBER(19)         NOT NULL,
    ROL_ID            NUMBER(19)         NOT NULL,
    ASIGNADO_EN       TIMESTAMP          DEFAULT SYSTIMESTAMP NOT NULL,
    ASIGNADO_POR      VARCHAR2(100 CHAR) DEFAULT 'SISTEMA' NOT NULL,
    CONSTRAINT PK_FUNCIONARIO_ROL PRIMARY KEY (FUNCIONARIO_ID, ROL_ID),
    CONSTRAINT FK_FUNCROL_FUNC FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID) ON DELETE CASCADE,
    CONSTRAINT FK_FUNCROL_ROL FOREIGN KEY (ROL_ID) REFERENCES ROL (ID)
);

-- =====================================================================
-- 3. GESTIÓN COMERCIAL: USUARIOS, PREDIOS, MEDIDORES, CONTRATOS
-- =====================================================================

-- Usuario del servicio, persona natural o jurídica (RF-01, RF-02, RF-16, CU-01, CO-03)
-- RNF-04: el número de identificación se guarda cifrado con AES-256-GCM desde el backend.
--   NUMERO_IDENTIFICACION_CIFRADO : texto cifrado en Base64 (IV + ciphertext + tag)
--   NUMERO_IDENTIFICACION_HASH    : HMAC-SHA256 en hex del número normalizado (índice ciego);
--                                   permite unicidad (RN-09), login y búsqueda exacta (RF-03)
--   NUMERO_IDENTIFICACION_MASCARA : últimos 4 caracteres visibles, para pantallas y logs (RNF-20)
-- El formato del número (CC, CE, NIT con dígito de verificación, etc.) lo valida el backend antes de cifrar.
CREATE TABLE USUARIO (
    ID                             NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    CODIGO                         VARCHAR2(12 CHAR)   NOT NULL,
    TIPO_PERSONA                   VARCHAR2(8 CHAR)    NOT NULL,
    TIPO_IDENTIFICACION            VARCHAR2(3 CHAR)    NOT NULL,
    NUMERO_IDENTIFICACION_CIFRADO  VARCHAR2(255 CHAR)  NOT NULL,
    NUMERO_IDENTIFICACION_HASH     CHAR(64 CHAR)       NOT NULL,
    NUMERO_IDENTIFICACION_MASCARA  VARCHAR2(20 CHAR)   NOT NULL,
    NOMBRE_COMPLETO                VARCHAR2(150 CHAR)  NOT NULL,
    CORREO                         VARCHAR2(254 CHAR)  NOT NULL,
    TELEFONO                       VARCHAR2(13 CHAR)   NOT NULL,
    DIRECCION_NOTIFICACION         VARCHAR2(200 CHAR)  NOT NULL,
    MUNICIPIO_ID                   NUMBER(19)          NOT NULL,
    AUTORIZA_TRATAMIENTO_DATOS     CHAR(1)             NOT NULL,
    FECHA_AUTORIZACION_DATOS       TIMESTAMP           NOT NULL,
    ESTADO_VERIFICACION_RNEC       VARCHAR2(10 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    FECHA_VERIFICACION_RNEC        TIMESTAMP,
    ACTIVO                         CHAR(1)             DEFAULT 'S' NOT NULL,
    FECHA_INACTIVACION             TIMESTAMP,
    MOTIVO_INACTIVACION            VARCHAR2(300 CHAR),
    CREADO_EN                      TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR                     VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN                 TIMESTAMP,
    ACTUALIZADO_POR                VARCHAR2(100 CHAR),
    VERSION                        NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_USUARIO PRIMARY KEY (ID),
    CONSTRAINT UK_USUARIO_CODIGO UNIQUE (CODIGO),
    -- RN-09: identificación única por tipo y número
    CONSTRAINT UK_USUARIO_IDENTIFICACION UNIQUE (TIPO_IDENTIFICACION, NUMERO_IDENTIFICACION_HASH),
    CONSTRAINT FK_USUARIO_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    CONSTRAINT CK_USUARIO_CODIGO CHECK (REGEXP_LIKE(CODIGO, '^USR-[0-9]{8}$')),
    CONSTRAINT CK_USUARIO_TIPO_PERSONA CHECK (TIPO_PERSONA IN ('NATURAL','JURIDICA')),
    CONSTRAINT CK_USUARIO_TIPO_ID CHECK (TIPO_IDENTIFICACION IN ('CC','CE','TI','PA','PPT','NIT')),
    -- NIT <=> persona jurídica
    CONSTRAINT CK_USUARIO_PERSONA_ID CHECK (
        (TIPO_PERSONA = 'JURIDICA' AND TIPO_IDENTIFICACION = 'NIT')
     OR (TIPO_PERSONA = 'NATURAL'  AND TIPO_IDENTIFICACION <> 'NIT')),
    CONSTRAINT CK_USUARIO_ID_CIFRADO CHECK (REGEXP_LIKE(NUMERO_IDENTIFICACION_CIFRADO, '^[A-Za-z0-9+/]{20,}={0,2}$')),
    CONSTRAINT CK_USUARIO_ID_HASH CHECK (REGEXP_LIKE(NUMERO_IDENTIFICACION_HASH, '^[0-9a-f]{64}$')),
    CONSTRAINT CK_USUARIO_ID_MASCARA CHECK (REGEXP_LIKE(NUMERO_IDENTIFICACION_MASCARA, '^\*+[A-Z0-9-]{1,4}$')),
    -- Persona natural: solo letras (con tildes y ñ), espacios, apóstrofo, punto y guion.
    -- Persona jurídica: razón social, admite dígitos y signos comunes.
    CONSTRAINT CK_USUARIO_NOMBRE CHECK (
        NOMBRE_COMPLETO = TRIM(NOMBRE_COMPLETO) AND LENGTH(NOMBRE_COMPLETO) >= 3
        AND ((TIPO_PERSONA = 'NATURAL'  AND REGEXP_LIKE(NOMBRE_COMPLETO, '^[[:alpha:]][[:alpha:] .''-]*$'))
          OR (TIPO_PERSONA = 'JURIDICA' AND REGEXP_LIKE(NOMBRE_COMPLETO, '^[[:alnum:]][[:alnum:] .,&''()/-]*$')))),
    CONSTRAINT CK_USUARIO_CORREO CHECK (
        CORREO = LOWER(TRIM(CORREO)) AND REGEXP_LIKE(CORREO, '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$')),
    -- Celular de 10 dígitos que inicia en 3 o fijo de 10 dígitos que inicia en 60; +57 opcional
    CONSTRAINT CK_USUARIO_TELEFONO CHECK (REGEXP_LIKE(TELEFONO, '^(\+57)?(3[0-9]{9}|60[0-9]{8})$')),
    CONSTRAINT CK_USUARIO_DIRECCION CHECK (LENGTH(TRIM(DIRECCION_NOTIFICACION)) >= 5),
    -- Ley 1581 de 2012: sin autorización de tratamiento de datos no hay registro
    CONSTRAINT CK_USUARIO_AUTORIZA CHECK (AUTORIZA_TRATAMIENTO_DATOS = 'S'),
    -- CU-01 (4b): si la RNEC no responde el usuario queda PENDIENTE de validación
    CONSTRAINT CK_USUARIO_RNEC CHECK (ESTADO_VERIFICACION_RNEC IN ('PENDIENTE','VERIFICADO','RECHAZADO')),
    CONSTRAINT CK_USUARIO_RNEC_FECHA CHECK (
        ESTADO_VERIFICACION_RNEC = 'PENDIENTE' OR FECHA_VERIFICACION_RNEC IS NOT NULL),
    CONSTRAINT CK_USUARIO_ACTIVO CHECK (ACTIVO IN ('S','N')),
    CONSTRAINT CK_USUARIO_INACTIVACION CHECK (
        (ACTIVO = 'S' AND FECHA_INACTIVACION IS NULL AND MOTIVO_INACTIVACION IS NULL)
     OR (ACTIVO = 'N' AND FECHA_INACTIVACION IS NOT NULL AND MOTIVO_INACTIVACION IS NOT NULL)),
    CONSTRAINT CK_USUARIO_VERSION CHECK (VERSION >= 0)
);

-- Cuenta del portal de autogestión (IU-01, RF-07, RF-25, RF-26). Rol CIUDADANO (P-16).
-- El asesor registra al usuario; el ciudadano activa la cuenta con un enlace a su correo (P-13).
CREATE TABLE CUENTA_PORTAL (
    USUARIO_ID          NUMBER(19)         NOT NULL,
    ESTADO              VARCHAR2(12 CHAR)  DEFAULT 'PENDIENTE' NOT NULL,
    PASSWORD_HASH       VARCHAR2(255 CHAR),
    INTENTOS_FALLIDOS   NUMBER(2)          DEFAULT 0 NOT NULL,
    BLOQUEADA_HASTA     TIMESTAMP,
    ULTIMO_ACCESO       TIMESTAMP,
    CAMBIO_PASSWORD_EN  TIMESTAMP,
    CREADO_EN           TIMESTAMP          DEFAULT SYSTIMESTAMP NOT NULL,
    VERSION             NUMBER(10)         DEFAULT 0 NOT NULL,
    CONSTRAINT PK_CUENTA_PORTAL PRIMARY KEY (USUARIO_ID),
    CONSTRAINT FK_CUENTA_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT CK_CUENTA_ESTADO CHECK (ESTADO IN ('PENDIENTE','ACTIVA','INACTIVA')),
    -- Hash BCrypt/Argon2 (>= 60 caracteres); obligatorio desde la activación
    CONSTRAINT CK_CUENTA_PASSWORD CHECK (
        (ESTADO = 'PENDIENTE' AND PASSWORD_HASH IS NULL)
     OR (ESTADO <> 'PENDIENTE' AND LENGTH(PASSWORD_HASH) >= 60 AND CAMBIO_PASSWORD_EN IS NOT NULL)),
    CONSTRAINT CK_CUENTA_INTENTOS CHECK (INTENTOS_FALLIDOS BETWEEN 0 AND 99),
    CONSTRAINT CK_CUENTA_VERSION CHECK (VERSION >= 0)
);

-- Tokens de un solo uso para activar la cuenta o recuperar la contraseña (RF-26, P-13: 24 h)
CREATE TABLE TOKEN_ACCESO (
    ID           NUMBER(19)         GENERATED ALWAYS AS IDENTITY,
    USUARIO_ID   NUMBER(19)         NOT NULL,
    TIPO         VARCHAR2(12 CHAR)  NOT NULL,
    TOKEN_HASH   CHAR(64 CHAR)      NOT NULL,
    CREADO_EN    TIMESTAMP          DEFAULT SYSTIMESTAMP NOT NULL,
    EXPIRA_EN    TIMESTAMP          NOT NULL,
    USADO_EN     TIMESTAMP,
    CONSTRAINT PK_TOKEN_ACCESO PRIMARY KEY (ID),
    CONSTRAINT UK_TOKEN_HASH UNIQUE (TOKEN_HASH),
    CONSTRAINT FK_TOKEN_CUENTA FOREIGN KEY (USUARIO_ID) REFERENCES CUENTA_PORTAL (USUARIO_ID),
    CONSTRAINT CK_TOKEN_TIPO CHECK (TIPO IN ('ACTIVACION','RECUPERACION')),
    CONSTRAINT CK_TOKEN_HASH CHECK (REGEXP_LIKE(TOKEN_HASH, '^[0-9a-f]{64}$')),
    CONSTRAINT CK_TOKEN_EXPIRA CHECK (EXPIRA_EN > CREADO_EN AND EXPIRA_EN <= CREADO_EN + INTERVAL '2' DAY),
    CONSTRAINT CK_TOKEN_USO CHECK (USADO_EN IS NULL OR USADO_EN BETWEEN CREADO_EN AND EXPIRA_EN)
);

-- Predio: inmueble donde se presta el servicio (P-06)
CREATE TABLE PREDIO (
    ID               NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    CODIGO_PREDIO    VARCHAR2(12 CHAR)   NOT NULL,
    FICHA_CATASTRAL  VARCHAR2(30 CHAR),
    DIRECCION        VARCHAR2(200 CHAR)  NOT NULL,
    BARRIO_VEREDA    VARCHAR2(100 CHAR),
    MUNICIPIO_ID     NUMBER(19)          NOT NULL,
    SECTOR_ID        NUMBER(19),
    USO              VARCHAR2(12 CHAR)   NOT NULL,
    ESTRATO          NUMBER(1),
    CREADO_EN        TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR       VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN   TIMESTAMP,
    ACTUALIZADO_POR  VARCHAR2(100 CHAR),
    VERSION          NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_PREDIO PRIMARY KEY (ID),
    CONSTRAINT UK_PREDIO_CODIGO UNIQUE (CODIGO_PREDIO),
    CONSTRAINT UK_PREDIO_FICHA UNIQUE (FICHA_CATASTRAL),
    CONSTRAINT FK_PREDIO_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    -- El sector, si se indica, pertenece al mismo municipio del predio
    CONSTRAINT FK_PREDIO_SECTOR FOREIGN KEY (SECTOR_ID, MUNICIPIO_ID) REFERENCES SECTOR (ID, MUNICIPIO_ID),
    CONSTRAINT CK_PREDIO_CODIGO CHECK (REGEXP_LIKE(CODIGO_PREDIO, '^PRD-[0-9]{8}$')),
    -- P-06: número predial nacional IGAC de 30 dígitos; opcional
    CONSTRAINT CK_PREDIO_FICHA CHECK (FICHA_CATASTRAL IS NULL OR REGEXP_LIKE(FICHA_CATASTRAL, '^[0-9]{30}$')),
    CONSTRAINT CK_PREDIO_DIRECCION CHECK (LENGTH(TRIM(DIRECCION)) >= 5),
    CONSTRAINT CK_PREDIO_USO CHECK (USO IN ('RESIDENCIAL','COMERCIAL','INDUSTRIAL','OFICIAL')),
    -- Estrato socioeconómico 1..6 aplica solo a uso residencial (RN-08)
    CONSTRAINT CK_PREDIO_ESTRATO CHECK (
        (USO = 'RESIDENCIAL' AND ESTRATO IS NOT NULL AND ESTRATO BETWEEN 1 AND 6)
     OR (USO <> 'RESIDENCIAL' AND ESTRATO IS NULL)),
    CONSTRAINT CK_PREDIO_VERSION CHECK (VERSION >= 0)
);

-- Medidor de acueducto o gas instalado en un predio; el contrato lo referencia (P-06)
CREATE TABLE MEDIDOR (
    ID                 NUMBER(19)         GENERATED ALWAYS AS IDENTITY,
    SERIAL             VARCHAR2(30 CHAR)  NOT NULL,
    PREDIO_ID          NUMBER(19)         NOT NULL,
    TIPO_SERVICIO      VARCHAR2(15 CHAR)  NOT NULL,
    MARCA              VARCHAR2(60 CHAR),
    FECHA_INSTALACION  DATE               NOT NULL,
    LECTURA_INICIAL    NUMBER(12,3)       DEFAULT 0 NOT NULL,
    -- Última lectura CONFIRMADA: base de la lectura anterior del siguiente periodo
    LECTURA_ACTUAL     NUMBER(12,3)       DEFAULT 0 NOT NULL,
    ULTIMO_PERIODO     NUMBER(6),
    -- 'S' mientras una lectura de este medidor espera la crítica (P-07)
    LECTURA_EN_REVISION CHAR(1)           DEFAULT 'N' NOT NULL,
    ESTADO             VARCHAR2(10 CHAR)  DEFAULT 'ACTIVO' NOT NULL,
    FECHA_RETIRO       DATE,
    CREADO_EN          TIMESTAMP          DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR         VARCHAR2(100 CHAR) DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN     TIMESTAMP,
    ACTUALIZADO_POR    VARCHAR2(100 CHAR),
    VERSION            NUMBER(10)         DEFAULT 0 NOT NULL,
    CONSTRAINT PK_MEDIDOR PRIMARY KEY (ID),
    CONSTRAINT UK_MEDIDOR_SERIAL UNIQUE (SERIAL),
    -- Clave candidata usada por CONTRATO_SERVICIO para garantizar que el medidor
    -- es del mismo predio y del mismo tipo de servicio que el contrato
    CONSTRAINT UK_MEDIDOR_PREDIO_TIPO UNIQUE (ID, PREDIO_ID, TIPO_SERVICIO),
    CONSTRAINT FK_MEDIDOR_PREDIO FOREIGN KEY (PREDIO_ID) REFERENCES PREDIO (ID),
    CONSTRAINT CK_MEDIDOR_SERIAL CHECK (REGEXP_LIKE(SERIAL, '^[A-Z0-9-]{4,30}$')),
    -- Alcantarillado no lleva medidor propio (se liquida sobre el consumo de acueducto)
    CONSTRAINT CK_MEDIDOR_TIPO CHECK (TIPO_SERVICIO IN ('ACUEDUCTO','GAS')),
    CONSTRAINT CK_MEDIDOR_LECTURAS CHECK (LECTURA_INICIAL >= 0 AND LECTURA_ACTUAL >= LECTURA_INICIAL),
    CONSTRAINT CK_MEDIDOR_PERIODO CHECK (ULTIMO_PERIODO IS NULL OR MOD(ULTIMO_PERIODO, 100) BETWEEN 1 AND 12),
    CONSTRAINT CK_MEDIDOR_REVISION CHECK (LECTURA_EN_REVISION IN ('S','N')),
    CONSTRAINT CK_MEDIDOR_ESTADO CHECK (ESTADO IN ('ACTIVO','RETIRADO')),
    CONSTRAINT CK_MEDIDOR_RETIRO CHECK (
        (ESTADO = 'ACTIVO' AND FECHA_RETIRO IS NULL)
     OR (ESTADO = 'RETIRADO' AND FECHA_RETIRO IS NOT NULL AND FECHA_RETIRO >= FECHA_INSTALACION)),
    CONSTRAINT CK_MEDIDOR_VERSION CHECK (VERSION >= 0)
);

-- Tarifa por servicio y municipio, con vigencia (P-08, RN-08).
--   ACUEDUCTO y ALCANTARILLADO: metodología CRA (Res. 688/2014). Costo de referencia
--     igual para todos los estratos: cargo fijo ($/suscriptor/mes) y valor por m³ en
--     los rangos básico (hasta CONSUMO_BASICO_M3, 13 m³ por Res. CRA 750/2016),
--     complementario y suntuario (desde CONSUMO_SUNTUARIO_DESDE_M3). Los subsidios y
--     contribuciones por estrato o uso están en FACTOR_SUBSIDIO.
--   GAS (GLP por redes, CREG): cargo fijo + un único valor por m³, sin rangos ni subsidios.
CREATE TABLE TARIFA (
    ID                          NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    TIPO_SERVICIO               VARCHAR2(15 CHAR)   NOT NULL,
    MUNICIPIO_ID                NUMBER(19)          NOT NULL,
    CARGO_FIJO                  NUMBER(14,2)        NOT NULL,
    VALOR_M3_BASICO             NUMBER(14,4)        NOT NULL,
    VALOR_M3_COMPLEMENTARIO     NUMBER(14,4),
    VALOR_M3_SUNTUARIO          NUMBER(14,4),
    CONSUMO_BASICO_M3           NUMBER(6,2),
    CONSUMO_SUNTUARIO_DESDE_M3  NUMBER(6,2),
    VIGENTE_DESDE               DATE                NOT NULL,
    VIGENTE_HASTA               DATE,
    RESOLUCION                  VARCHAR2(80 CHAR)   NOT NULL,
    CREADO_EN                   TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR                  VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN              TIMESTAMP,
    ACTUALIZADO_POR             VARCHAR2(100 CHAR),
    VERSION                     NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_TARIFA PRIMARY KEY (ID),
    CONSTRAINT UK_TARIFA_VIGENCIA UNIQUE (TIPO_SERVICIO, MUNICIPIO_ID, VIGENTE_DESDE),
    CONSTRAINT FK_TARIFA_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    CONSTRAINT CK_TARIFA_TIPO CHECK (TIPO_SERVICIO IN ('ACUEDUCTO','ALCANTARILLADO','GAS')),
    CONSTRAINT CK_TARIFA_VALORES CHECK (
        CARGO_FIJO >= 0 AND VALOR_M3_BASICO >= 0
        AND (VALOR_M3_COMPLEMENTARIO IS NULL OR VALOR_M3_COMPLEMENTARIO >= 0)
        AND (VALOR_M3_SUNTUARIO IS NULL OR VALOR_M3_SUNTUARIO >= 0)),
    CONSTRAINT CK_TARIFA_RANGOS CHECK (
        (TIPO_SERVICIO = 'GAS'
            AND VALOR_M3_COMPLEMENTARIO IS NULL AND VALOR_M3_SUNTUARIO IS NULL
            AND CONSUMO_BASICO_M3 IS NULL AND CONSUMO_SUNTUARIO_DESDE_M3 IS NULL)
     OR (TIPO_SERVICIO <> 'GAS'
            AND VALOR_M3_COMPLEMENTARIO IS NOT NULL AND VALOR_M3_SUNTUARIO IS NOT NULL
            AND CONSUMO_BASICO_M3 IS NOT NULL AND CONSUMO_SUNTUARIO_DESDE_M3 IS NOT NULL
            AND CONSUMO_BASICO_M3 > 0 AND CONSUMO_SUNTUARIO_DESDE_M3 >= CONSUMO_BASICO_M3)),
    CONSTRAINT CK_TARIFA_FECHAS CHECK (
        VIGENTE_DESDE = TRUNC(VIGENTE_DESDE)
        AND (VIGENTE_HASTA IS NULL OR (VIGENTE_HASTA = TRUNC(VIGENTE_HASTA) AND VIGENTE_HASTA >= VIGENTE_DESDE))),
    CONSTRAINT CK_TARIFA_RESOLUCION CHECK (LENGTH(TRIM(RESOLUCION)) >= 5),
    CONSTRAINT CK_TARIFA_VERSION CHECK (VERSION >= 0)
);

-- Factores de subsidio (−) y contribución (+) por municipio, servicio, uso y estrato,
-- según el acuerdo municipal (P-08, RN-37, Ley 142 art. 99 y Ley 1450 de 2011 art. 125).
--   * Subsidio máximo: estrato 1 −70 %, estrato 2 −40 %, estrato 3 −15 %.
--   * Estrato 4 y uso oficial: 0 %. Estratos 5 y 6, comercial e industrial: contribución >= 0.
--   * El subsidio aplica solo al consumo básico; la contribución al cargo fijo y al consumo.
CREATE TABLE FACTOR_SUBSIDIO (
    ID                 NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    MUNICIPIO_ID       NUMBER(19)          NOT NULL,
    TIPO_SERVICIO      VARCHAR2(15 CHAR)   NOT NULL,
    USO                VARCHAR2(12 CHAR)   NOT NULL,
    ESTRATO            NUMBER(1),
    PORCENTAJE         NUMBER(5,2)         NOT NULL,
    VIGENTE_DESDE      DATE                NOT NULL,
    VIGENTE_HASTA      DATE,
    ACUERDO_MUNICIPAL  VARCHAR2(80 CHAR)   NOT NULL,
    CREADO_EN          TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR         VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    VERSION            NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_FACTOR_SUBSIDIO PRIMARY KEY (ID),
    CONSTRAINT UK_FACTOR_VIGENCIA UNIQUE (MUNICIPIO_ID, TIPO_SERVICIO, USO, ESTRATO, VIGENTE_DESDE),
    CONSTRAINT FK_FACTOR_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    CONSTRAINT CK_FACTOR_TIPO CHECK (TIPO_SERVICIO IN ('ACUEDUCTO','ALCANTARILLADO')),
    CONSTRAINT CK_FACTOR_USO CHECK (USO IN ('RESIDENCIAL','COMERCIAL','INDUSTRIAL','OFICIAL')),
    CONSTRAINT CK_FACTOR_ESTRATO CHECK (
        (USO = 'RESIDENCIAL' AND ESTRATO IS NOT NULL AND ESTRATO BETWEEN 1 AND 6)
     OR (USO <> 'RESIDENCIAL' AND ESTRATO IS NULL)),
    CONSTRAINT CK_FACTOR_TOPES CHECK (
        (USO = 'RESIDENCIAL' AND ESTRATO = 1 AND PORCENTAJE BETWEEN -70 AND 0)
     OR (USO = 'RESIDENCIAL' AND ESTRATO = 2 AND PORCENTAJE BETWEEN -40 AND 0)
     OR (USO = 'RESIDENCIAL' AND ESTRATO = 3 AND PORCENTAJE BETWEEN -15 AND 0)
     OR (USO = 'RESIDENCIAL' AND ESTRATO = 4 AND PORCENTAJE = 0)
     OR (USO = 'RESIDENCIAL' AND ESTRATO IN (5,6) AND PORCENTAJE BETWEEN 0 AND 100)
     OR (USO IN ('COMERCIAL','INDUSTRIAL') AND PORCENTAJE BETWEEN 0 AND 100)
     OR (USO = 'OFICIAL' AND PORCENTAJE = 0)),
    CONSTRAINT CK_FACTOR_FECHAS CHECK (
        VIGENTE_DESDE = TRUNC(VIGENTE_DESDE)
        AND (VIGENTE_HASTA IS NULL OR (VIGENTE_HASTA = TRUNC(VIGENTE_HASTA) AND VIGENTE_HASTA >= VIGENTE_DESDE))),
    CONSTRAINT CK_FACTOR_ACUERDO CHECK (LENGTH(TRIM(ACUERDO_MUNICIPAL)) >= 5),
    CONSTRAINT CK_FACTOR_VERSION CHECK (VERSION >= 0)
);

-- Contrato de servicio: vincula usuario + predio + tipo de servicio (RF-04, F-02, RN-01, P-04, P-06, P-11).
-- La tarifa no se fija en el contrato: cada línea de factura toma la tarifa vigente del periodo.
CREATE TABLE CONTRATO_SERVICIO (
    ID                  NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    NUMERO_CONTRATO     VARCHAR2(12 CHAR)   NOT NULL,
    USUARIO_ID          NUMBER(19)          NOT NULL,
    PREDIO_ID           NUMBER(19)          NOT NULL,
    TIPO_SERVICIO       VARCHAR2(15 CHAR)   NOT NULL,
    MEDIDOR_ID          NUMBER(19),
    FECHA_VINCULACION   DATE                NOT NULL,
    ESTADO              VARCHAR2(12 CHAR)   DEFAULT 'ACTIVO' NOT NULL,
    FECHA_ESTADO        TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    MOTIVO_ESTADO       VARCHAR2(300 CHAR),
    FUNCIONARIO_ID      NUMBER(19)          NOT NULL,
    CREADO_EN           TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR          VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN      TIMESTAMP,
    ACTUALIZADO_POR     VARCHAR2(100 CHAR),
    VERSION             NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_CONTRATO PRIMARY KEY (ID),
    CONSTRAINT UK_CONTRATO_NUMERO UNIQUE (NUMERO_CONTRATO),
    CONSTRAINT FK_CONTRATO_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT FK_CONTRATO_PREDIO FOREIGN KEY (PREDIO_ID) REFERENCES PREDIO (ID),
    -- El medidor debe pertenecer al mismo predio y ser del mismo tipo de servicio
    CONSTRAINT FK_CONTRATO_MEDIDOR FOREIGN KEY (MEDIDOR_ID, PREDIO_ID, TIPO_SERVICIO)
        REFERENCES MEDIDOR (ID, PREDIO_ID, TIPO_SERVICIO),
    CONSTRAINT FK_CONTRATO_FUNCIONARIO FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_CONTRATO_NUMERO CHECK (REGEXP_LIKE(NUMERO_CONTRATO, '^CTR-[0-9]{8}$')),
    CONSTRAINT CK_CONTRATO_TIPO CHECK (TIPO_SERVICIO IN ('ACUEDUCTO','ALCANTARILLADO','GAS')),
    -- RF-04 / P-06: acueducto y gas requieren medidor; alcantarillado no
    CONSTRAINT CK_CONTRATO_MEDIDOR CHECK (
        (TIPO_SERVICIO = 'ALCANTARILLADO' AND MEDIDOR_ID IS NULL)
     OR (TIPO_SERVICIO <> 'ALCANTARILLADO' AND MEDIDOR_ID IS NOT NULL)),
    CONSTRAINT CK_CONTRATO_FECHA CHECK (FECHA_VINCULACION = TRUNC(FECHA_VINCULACION)),
    CONSTRAINT CK_CONTRATO_ESTADO CHECK (ESTADO IN ('ACTIVO','SUSPENDIDO','CANCELADO')),
    CONSTRAINT CK_CONTRATO_MOTIVO CHECK (ESTADO = 'ACTIVO' OR MOTIVO_ESTADO IS NOT NULL),
    CONSTRAINT CK_CONTRATO_VERSION CHECK (VERSION >= 0)
);

-- Lectura mensual de un medidor con crítica antes de facturar (P-07, RN-35).
--   REGISTRADA  : estado transitorio al insertar; el trigger aplica la crítica al terminar la sentencia.
--   CONFIRMADA  : desviación <= LECTURA_DESVIACION_PCT respecto al promedio, o confirmada por el Asesor.
--   EN_REVISION : desviación mayor; no se factura hasta que el Asesor la confirme o la rechace.
--   ESTIMADA    : sin lectura (CAUSA_NO_LECTURA) o rechazada en la revisión; consumo = promedio de 6 periodos.
CREATE TABLE LECTURA (
    ID                   NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    MEDIDOR_ID           NUMBER(19)          NOT NULL,
    PERIODO              NUMBER(6)           NOT NULL,
    FECHA_LECTURA        DATE                NOT NULL,
    LECTURA_ANTERIOR     NUMBER(12,3)        NOT NULL,
    LECTURA_ACTUAL       NUMBER(12,3),
    CONSUMO              NUMBER(12,3),
    ESTADO               VARCHAR2(12 CHAR)   DEFAULT 'REGISTRADA' NOT NULL,
    ORIGEN               VARCHAR2(10 CHAR)   DEFAULT 'MANUAL' NOT NULL,
    CAUSA_NO_LECTURA     VARCHAR2(20 CHAR),
    PROMEDIO_REFERENCIA  NUMBER(12,3),
    DESVIACION_PCT       NUMBER(9,2),
    OBSERVACION          VARCHAR2(300 CHAR),
    REGISTRADA_POR       NUMBER(19),
    REVISADA_POR         NUMBER(19),
    FECHA_REVISION       TIMESTAMP,
    CREADO_EN            TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_LECTURA PRIMARY KEY (ID),
    CONSTRAINT UK_LECTURA_PERIODO UNIQUE (MEDIDOR_ID, PERIODO),
    CONSTRAINT FK_LECTURA_MEDIDOR FOREIGN KEY (MEDIDOR_ID) REFERENCES MEDIDOR (ID),
    CONSTRAINT FK_LECTURA_FUNCIONARIO FOREIGN KEY (REGISTRADA_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT FK_LECTURA_REVISOR FOREIGN KEY (REVISADA_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_LECTURA_PERIODO CHECK (PERIODO BETWEEN 200001 AND 209912 AND MOD(PERIODO, 100) BETWEEN 1 AND 12),
    CONSTRAINT CK_LECTURA_FECHA CHECK (FECHA_LECTURA = TRUNC(FECHA_LECTURA)),
    CONSTRAINT CK_LECTURA_ESTADO CHECK (ESTADO IN ('REGISTRADA','EN_REVISION','CONFIRMADA','ESTIMADA')),
    -- P-07: registro manual, carga CSV o estimación automática del lote de facturación
    CONSTRAINT CK_LECTURA_ORIGEN CHECK (ORIGEN IN ('MANUAL','ARCHIVO','SISTEMA')),
    CONSTRAINT CK_LECTURA_REGISTRO CHECK (
        (ORIGEN = 'SISTEMA' AND REGISTRADA_POR IS NULL AND LECTURA_ACTUAL IS NULL)
     OR (ORIGEN <> 'SISTEMA' AND REGISTRADA_POR IS NOT NULL)),
    CONSTRAINT CK_LECTURA_CAUSA CHECK (CAUSA_NO_LECTURA IS NULL OR CAUSA_NO_LECTURA IN
        ('MEDIDOR_DANADO','PREDIO_CERRADO','ACCESO_IMPEDIDO','MEDIDOR_ILEGIBLE','OTRA')),
    -- Hay lectura del medidor o hay causa de no lectura, nunca ambas
    CONSTRAINT CK_LECTURA_TOMADA CHECK (
        (LECTURA_ACTUAL IS NOT NULL AND CAUSA_NO_LECTURA IS NULL AND LECTURA_ANTERIOR >= 0
            AND LECTURA_ACTUAL >= LECTURA_ANTERIOR)
     OR (LECTURA_ACTUAL IS NULL AND CAUSA_NO_LECTURA IS NOT NULL AND LECTURA_ANTERIOR >= 0)),
    CONSTRAINT CK_LECTURA_CONSUMO CHECK (
        (ESTADO = 'REGISTRADA' AND LECTURA_ACTUAL IS NULL AND CONSUMO IS NULL)
     OR (ESTADO IN ('REGISTRADA','EN_REVISION','CONFIRMADA') AND LECTURA_ACTUAL IS NOT NULL
            AND CONSUMO IS NOT NULL AND CONSUMO = LECTURA_ACTUAL - LECTURA_ANTERIOR)
     OR (ESTADO = 'ESTIMADA' AND CONSUMO IS NOT NULL AND PROMEDIO_REFERENCIA IS NOT NULL
            AND CONSUMO = PROMEDIO_REFERENCIA AND CONSUMO >= 0)),
    CONSTRAINT CK_LECTURA_CRITICA CHECK (
        (ESTADO NOT IN ('EN_REVISION','ESTIMADA') OR PROMEDIO_REFERENCIA IS NOT NULL)
        AND (PROMEDIO_REFERENCIA IS NULL OR PROMEDIO_REFERENCIA >= 0)
        AND (DESVIACION_PCT IS NULL OR DESVIACION_PCT >= 0)),
    -- Una lectura tomada solo pasa a ESTIMADA si el Asesor la rechazó en la revisión
    CONSTRAINT CK_LECTURA_REVISION CHECK (
        (REVISADA_POR IS NULL AND FECHA_REVISION IS NULL
            AND (ESTADO <> 'ESTIMADA' OR LECTURA_ACTUAL IS NULL))
     OR (REVISADA_POR IS NOT NULL AND FECHA_REVISION IS NOT NULL AND ESTADO IN ('CONFIRMADA','ESTIMADA'))),
    CONSTRAINT CK_LECTURA_OBSERVACION CHECK (CAUSA_NO_LECTURA <> 'OTRA' OR OBSERVACION IS NOT NULL)
);

-- =====================================================================
-- 4. FACTURACIÓN (RF-05, F-03, DE-01, RN-02, P-05, P-10, RN-33, RN-34)
-- =====================================================================

-- Ejecución del proceso batch mensual (SWR-15)
CREATE TABLE LOTE_FACTURACION (
    ID                NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    PERIODO           NUMBER(6)           NOT NULL,
    ESTADO            VARCHAR2(12 CHAR)   DEFAULT 'EN_PROCESO' NOT NULL,
    INICIADO_EN       TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    FINALIZADO_EN     TIMESTAMP,
    TOTAL_PREDIOS     NUMBER(10)          DEFAULT 0 NOT NULL,
    TOTAL_FACTURAS    NUMBER(10)          DEFAULT 0 NOT NULL,
    TOTAL_ERRORES     NUMBER(10)          DEFAULT 0 NOT NULL,
    VALOR_TOTAL       NUMBER(16,2)        DEFAULT 0 NOT NULL,
    DETALLE_ERRORES   CLOB,
    EJECUTADO_POR     VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    CONSTRAINT PK_LOTE_FACTURACION PRIMARY KEY (ID),
    CONSTRAINT CK_LOTE_PERIODO CHECK (PERIODO BETWEEN 200001 AND 209912 AND MOD(PERIODO, 100) BETWEEN 1 AND 12),
    CONSTRAINT CK_LOTE_ESTADO CHECK (ESTADO IN ('EN_PROCESO','COMPLETADO','FALLIDO')),
    CONSTRAINT CK_LOTE_FIN CHECK (
        (ESTADO = 'EN_PROCESO' AND FINALIZADO_EN IS NULL)
     OR (ESTADO <> 'EN_PROCESO' AND FINALIZADO_EN IS NOT NULL AND FINALIZADO_EN >= INICIADO_EN)),
    CONSTRAINT CK_LOTE_TOTALES CHECK (
        TOTAL_PREDIOS >= 0 AND TOTAL_FACTURAS >= 0 AND TOTAL_ERRORES >= 0
        AND TOTAL_FACTURAS + TOTAL_ERRORES <= TOTAL_PREDIOS AND VALOR_TOTAL >= 0),
    CONSTRAINT CK_LOTE_ERRORES_JSON CHECK (DETALLE_ERRORES IS JSON)
);

-- Factura por usuario, predio y periodo; agrupa los servicios en LINEA_FACTURA (P-05).
-- Los totales los mantienen los triggers de LINEA_FACTURA y PAGO; el cliente no los escribe.
--   SALDO_PENDIENTE  = TOTAL_A_PAGAR + VALOR_AJUSTES − VALOR_PAGADO
--   Valor exigible   = SALDO_PENDIENTE − VALOR_EN_RECLAMO   (RN-33: lo reclamado no se cobra)
-- PAGADA se deriva sola cuando el saldo llega a cero; no se asigna a mano.
CREATE TABLE FACTURA (
    ID                   NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    NUMERO_FACTURA       VARCHAR2(20 CHAR)   NOT NULL,
    USUARIO_ID           NUMBER(19)          NOT NULL,
    PREDIO_ID            NUMBER(19)          NOT NULL,
    LOTE_ID              NUMBER(19),
    PERIODO              NUMBER(6)           NOT NULL,
    FECHA_EMISION        DATE                NOT NULL,
    FECHA_VENCIMIENTO    DATE                NOT NULL,
    NUMERO_LINEAS        NUMBER(3)           DEFAULT 0 NOT NULL,
    TOTAL_A_PAGAR        NUMBER(14,2)        DEFAULT 0 NOT NULL,
    VALOR_AJUSTES        NUMBER(14,2)        DEFAULT 0 NOT NULL,
    VALOR_PAGADO         NUMBER(14,2)        DEFAULT 0 NOT NULL,
    VALOR_EN_RECLAMO     NUMBER(14,2)        DEFAULT 0 NOT NULL,
    SALDO_PENDIENTE      NUMBER(14,2)        DEFAULT 0 NOT NULL,
    ESTADO               VARCHAR2(10 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    FECHA_ESTADO         TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    MOTIVO_ANULACION     VARCHAR2(500 CHAR),
    ANULADA_POR          NUMBER(19),
    REEXPEDICION_DE_ID   NUMBER(19),
    ESTADO_SYNC_ERP      VARCHAR2(12 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    REFERENCIA_ERP       VARCHAR2(60 CHAR),
    FECHA_SYNC_ERP       TIMESTAMP,
    CREADO_EN            TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR           VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN       TIMESTAMP,
    ACTUALIZADO_POR      VARCHAR2(100 CHAR),
    VERSION              NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_FACTURA PRIMARY KEY (ID),
    CONSTRAINT UK_FACTURA_NUMERO UNIQUE (NUMERO_FACTURA),
    -- Clave candidata para que la reexpedición sea del mismo usuario, predio y periodo
    CONSTRAINT UK_FACTURA_CLAVE UNIQUE (ID, USUARIO_ID, PREDIO_ID, PERIODO),
    -- P-10: una factura anulada se reexpide una sola vez
    CONSTRAINT UK_FACTURA_REEXPEDICION UNIQUE (REEXPEDICION_DE_ID),
    CONSTRAINT FK_FACTURA_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT FK_FACTURA_PREDIO FOREIGN KEY (PREDIO_ID) REFERENCES PREDIO (ID),
    CONSTRAINT FK_FACTURA_LOTE FOREIGN KEY (LOTE_ID) REFERENCES LOTE_FACTURACION (ID),
    CONSTRAINT FK_FACTURA_ANULADA_POR FOREIGN KEY (ANULADA_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT FK_FACTURA_REEXPEDICION FOREIGN KEY (REEXPEDICION_DE_ID, USUARIO_ID, PREDIO_ID, PERIODO)
        REFERENCES FACTURA (ID, USUARIO_ID, PREDIO_ID, PERIODO),
    CONSTRAINT CK_FACTURA_NUMERO CHECK (REGEXP_LIKE(NUMERO_FACTURA, '^FAC-[0-9]{6}-[0-9]{7}$')),
    CONSTRAINT CK_FACTURA_PERIODO CHECK (PERIODO BETWEEN 200001 AND 209912 AND MOD(PERIODO, 100) BETWEEN 1 AND 12),
    CONSTRAINT CK_FACTURA_FECHAS CHECK (
        FECHA_EMISION = TRUNC(FECHA_EMISION) AND FECHA_VENCIMIENTO = TRUNC(FECHA_VENCIMIENTO)
        AND FECHA_VENCIMIENTO > FECHA_EMISION),
    -- Cuadre de saldos
    CONSTRAINT CK_FACTURA_VALORES CHECK (
        NUMERO_LINEAS >= 0 AND TOTAL_A_PAGAR >= 0 AND VALOR_AJUSTES <= 0 AND VALOR_PAGADO >= 0
        AND SALDO_PENDIENTE = TOTAL_A_PAGAR + VALOR_AJUSTES - VALOR_PAGADO
        AND SALDO_PENDIENTE >= 0
        AND VALOR_EN_RECLAMO BETWEEN 0 AND SALDO_PENDIENTE),
    CONSTRAINT CK_FACTURA_ESTADO CHECK (ESTADO IN ('PENDIENTE','VENCIDA','EN_ACUERDO','PAGADA','ANULADA')),
    CONSTRAINT CK_FACTURA_PAGADA CHECK (ESTADO <> 'PAGADA' OR SALDO_PENDIENTE = 0),
    -- Al confirmar la transacción la factura tiene al menos una línea y, si no está saldada, saldo positivo
    CONSTRAINT CK_FACTURA_COMPLETA CHECK (
        NUMERO_LINEAS > 0 AND (ESTADO IN ('PAGADA','ANULADA') OR SALDO_PENDIENTE > 0))
        DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT CK_FACTURA_ANULACION CHECK (
        (ESTADO = 'ANULADA' AND MOTIVO_ANULACION IS NOT NULL AND LENGTH(TRIM(MOTIVO_ANULACION)) BETWEEN 10 AND 500
            AND ANULADA_POR IS NOT NULL)
     OR (ESTADO <> 'ANULADA' AND MOTIVO_ANULACION IS NULL AND ANULADA_POR IS NULL)),
    CONSTRAINT CK_FACTURA_REEXPEDICION_ID CHECK (REEXPEDICION_DE_ID IS NULL OR REEXPEDICION_DE_ID <> ID),
    CONSTRAINT CK_FACTURA_SYNC CHECK (ESTADO_SYNC_ERP IN ('PENDIENTE','SINCRONIZADA','ERROR')),
    CONSTRAINT CK_FACTURA_SYNC_REF CHECK (
        ESTADO_SYNC_ERP <> 'SINCRONIZADA' OR (REFERENCIA_ERP IS NOT NULL AND FECHA_SYNC_ERP IS NOT NULL)),
    CONSTRAINT CK_FACTURA_VERSION CHECK (VERSION >= 0)
);

-- Una línea por contrato (servicio) dentro de la factura del predio (P-05, P-08).
-- La liquidación la verifica el trigger contra la tarifa, el factor y la lectura:
--   CONSUMO        = básico + complementario + suntuario
--   VALOR_CONSUMO  = ROUND(básico·VB + complementario·VC + suntuario·VS, 2)
--   SUBSIDIO       = ROUND(básico·VB · factor / 100, 2)                si factor < 0  (RN-37)
--   CONTRIBUCION   = ROUND((CARGO_FIJO + VALOR_CONSUMO) · factor / 100, 2) si factor > 0
--   TOTAL_LINEA    = CARGO_FIJO + VALOR_CONSUMO + SUBSIDIO + CONTRIBUCION + OTROS_CARGOS + INTERESES_MORA
-- VALOR_AJUSTE (<= 0) registra lo que se reconoce al resolver un reclamo sobre la línea.
CREATE TABLE LINEA_FACTURA (
    ID                       NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    FACTURA_ID               NUMBER(19)          NOT NULL,
    CONTRATO_ID              NUMBER(19)          NOT NULL,
    TIPO_SERVICIO            VARCHAR2(15 CHAR)   NOT NULL,
    TARIFA_ID                NUMBER(19)          NOT NULL,
    FACTOR_SUBSIDIO_ID       NUMBER(19),
    LECTURA_ID               NUMBER(19)          NOT NULL,
    CONSUMO                  NUMBER(12,3)        NOT NULL,
    CONSUMO_ESTIMADO         CHAR(1)             DEFAULT 'N' NOT NULL,
    CONSUMO_BASICO           NUMBER(12,3)        NOT NULL,
    CONSUMO_COMPLEMENTARIO   NUMBER(12,3)        DEFAULT 0 NOT NULL,
    CONSUMO_SUNTUARIO        NUMBER(12,3)        DEFAULT 0 NOT NULL,
    CARGO_FIJO               NUMBER(14,2)        NOT NULL,
    VALOR_CONSUMO            NUMBER(14,2)        NOT NULL,
    SUBSIDIO                 NUMBER(14,2)        DEFAULT 0 NOT NULL,
    CONTRIBUCION             NUMBER(14,2)        DEFAULT 0 NOT NULL,
    OTROS_CARGOS             NUMBER(14,2)        DEFAULT 0 NOT NULL,
    DETALLE_OTROS_CARGOS     VARCHAR2(300 CHAR),
    INTERESES_MORA           NUMBER(14,2)        DEFAULT 0 NOT NULL,
    TOTAL_LINEA              NUMBER(14,2)        NOT NULL,
    VALOR_AJUSTE             NUMBER(14,2)        DEFAULT 0 NOT NULL,
    ESTADO                   VARCHAR2(10 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    EN_RECLAMO               CHAR(1)             DEFAULT 'N' NOT NULL,
    PAGO_ID                  NUMBER(19),
    FECHA_PAGO               TIMESTAMP,
    CREADO_EN                TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    VERSION                  NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_LINEA_FACTURA PRIMARY KEY (ID),
    CONSTRAINT UK_LINEA_CONTRATO UNIQUE (FACTURA_ID, CONTRATO_ID),
    CONSTRAINT FK_LINEA_FACTURA FOREIGN KEY (FACTURA_ID) REFERENCES FACTURA (ID),
    CONSTRAINT FK_LINEA_CONTRATO FOREIGN KEY (CONTRATO_ID) REFERENCES CONTRATO_SERVICIO (ID),
    CONSTRAINT FK_LINEA_TARIFA FOREIGN KEY (TARIFA_ID) REFERENCES TARIFA (ID),
    CONSTRAINT FK_LINEA_FACTOR FOREIGN KEY (FACTOR_SUBSIDIO_ID) REFERENCES FACTOR_SUBSIDIO (ID),
    CONSTRAINT FK_LINEA_LECTURA FOREIGN KEY (LECTURA_ID) REFERENCES LECTURA (ID),
    -- FK_LINEA_PAGO se agrega después de crear PAGO
    CONSTRAINT CK_LINEA_TIPO CHECK (TIPO_SERVICIO IN ('ACUEDUCTO','ALCANTARILLADO','GAS')),
    -- Acueducto y alcantarillado llevan factor de subsidio/contribución; gas no (P-08)
    CONSTRAINT CK_LINEA_FACTOR CHECK (
        (TIPO_SERVICIO = 'GAS' AND FACTOR_SUBSIDIO_ID IS NULL AND SUBSIDIO = 0 AND CONTRIBUCION = 0
            AND CONSUMO_COMPLEMENTARIO = 0 AND CONSUMO_SUNTUARIO = 0)
     OR (TIPO_SERVICIO <> 'GAS' AND FACTOR_SUBSIDIO_ID IS NOT NULL)),
    CONSTRAINT CK_LINEA_CONSUMO CHECK (
        CONSUMO_BASICO >= 0 AND CONSUMO_COMPLEMENTARIO >= 0 AND CONSUMO_SUNTUARIO >= 0
        AND CONSUMO = CONSUMO_BASICO + CONSUMO_COMPLEMENTARIO + CONSUMO_SUNTUARIO),
    CONSTRAINT CK_LINEA_ESTIMADO CHECK (CONSUMO_ESTIMADO IN ('S','N')),
    CONSTRAINT CK_LINEA_VALORES CHECK (
        CARGO_FIJO >= 0 AND VALOR_CONSUMO >= 0 AND SUBSIDIO <= 0 AND CONTRIBUCION >= 0
        AND (SUBSIDIO = 0 OR CONTRIBUCION = 0)
        AND OTROS_CARGOS >= 0 AND INTERESES_MORA >= 0
        AND TOTAL_LINEA = CARGO_FIJO + VALOR_CONSUMO + SUBSIDIO + CONTRIBUCION + OTROS_CARGOS + INTERESES_MORA
        AND TOTAL_LINEA >= 0),
    CONSTRAINT CK_LINEA_OTROS CHECK (OTROS_CARGOS = 0 OR DETALLE_OTROS_CARGOS IS NOT NULL),
    CONSTRAINT CK_LINEA_AJUSTE CHECK (VALOR_AJUSTE BETWEEN -TOTAL_LINEA AND 0),
    -- EXONERADA: el reclamo se reconoció por el total pendiente de la línea
    CONSTRAINT CK_LINEA_ESTADO CHECK (ESTADO IN ('PENDIENTE','PAGADA','EXONERADA')),
    CONSTRAINT CK_LINEA_EXONERADA CHECK (ESTADO <> 'EXONERADA' OR TOTAL_LINEA + VALOR_AJUSTE = 0),
    CONSTRAINT CK_LINEA_RECLAMO CHECK (EN_RECLAMO = 'N' OR (EN_RECLAMO = 'S' AND ESTADO = 'PENDIENTE')),
    -- PAGO_ID nulo en una línea PAGADA = saldada por cumplimiento de un acuerdo de pago
    CONSTRAINT CK_LINEA_PAGO CHECK (
        (ESTADO = 'PAGADA' AND FECHA_PAGO IS NOT NULL)
     OR (ESTADO <> 'PAGADA' AND FECHA_PAGO IS NULL AND PAGO_ID IS NULL)),
    CONSTRAINT CK_LINEA_VERSION CHECK (VERSION >= 0)
);

-- =====================================================================
-- 5. CARTERA: ACUERDOS DE PAGO, COBRO PERSUASIVO Y ÓRDENES (RF-11, RF-12, RF-23, F-07,
--    RN-03, RN-07, RN-30, RN-36, RN-38, P-11, P-12)
-- =====================================================================

-- Los totales TOTAL_INCLUIDO, TOTAL_CAPITAL_CUOTAS y CUOTAS_REGISTRADAS los mantienen
-- los triggers de ACUERDO_FACTURA y CUOTA_ACUERDO; al COMMIT deben cuadrar con el acuerdo.
CREATE TABLE ACUERDO_PAGO (
    ID                     NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    NUMERO_ACUERDO         VARCHAR2(14 CHAR)   NOT NULL,
    USUARIO_ID             NUMBER(19)          NOT NULL,
    FECHA_ACUERDO          DATE                NOT NULL,
    TOTAL_DEUDA            NUMBER(14,2)        NOT NULL,
    CUOTA_INICIAL          NUMBER(14,2)        NOT NULL,
    TASA_INTERES_ANUAL     NUMBER(7,4)         DEFAULT 0 NOT NULL,
    NUMERO_CUOTAS          NUMBER(3)           NOT NULL,
    TOTAL_INCLUIDO         NUMBER(14,2)        DEFAULT 0 NOT NULL,
    TOTAL_CAPITAL_CUOTAS   NUMBER(14,2)        DEFAULT 0 NOT NULL,
    CUOTAS_REGISTRADAS     NUMBER(3)           DEFAULT 0 NOT NULL,
    ESTADO                 VARCHAR2(12 CHAR)   DEFAULT 'VIGENTE' NOT NULL,
    FECHA_ESTADO           TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    MOTIVO_ESTADO          VARCHAR2(300 CHAR),
    FUNCIONARIO_ID         NUMBER(19)          NOT NULL,
    CREADO_EN              TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR             VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    ACTUALIZADO_EN         TIMESTAMP,
    ACTUALIZADO_POR        VARCHAR2(100 CHAR),
    VERSION                NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_ACUERDO_PAGO PRIMARY KEY (ID),
    CONSTRAINT UK_ACUERDO_NUMERO UNIQUE (NUMERO_ACUERDO),
    CONSTRAINT FK_ACUERDO_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT FK_ACUERDO_FUNCIONARIO FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_ACUERDO_NUMERO CHECK (REGEXP_LIKE(NUMERO_ACUERDO, '^AP-[0-9]{4}-[0-9]{6}$')),
    CONSTRAINT CK_ACUERDO_FECHA CHECK (FECHA_ACUERDO = TRUNC(FECHA_ACUERDO)),
    -- P-12: cuota inicial obligatoria (el mínimo porcentual lo valida el trigger con el parámetro)
    CONSTRAINT CK_ACUERDO_VALORES CHECK (TOTAL_DEUDA > 0 AND CUOTA_INICIAL > 0 AND CUOTA_INICIAL < TOTAL_DEUDA),
    -- RN-38: tope por la tasa de usura; el tope residencial (6 % civil) lo valida ACUERDO_FACTURA
    CONSTRAINT CK_ACUERDO_TASA CHECK (TASA_INTERES_ANUAL BETWEEN 0 AND 100),
    -- P-12: entre 2 y 24 cuotas mensuales, sin contar la cuota inicial (cuota 0)
    CONSTRAINT CK_ACUERDO_CUOTAS CHECK (NUMERO_CUOTAS BETWEEN 2 AND 24),
    CONSTRAINT CK_ACUERDO_TOTALES CHECK (
        TOTAL_INCLUIDO >= 0 AND TOTAL_CAPITAL_CUOTAS >= 0 AND CUOTAS_REGISTRADAS >= 0),
    CONSTRAINT CK_ACUERDO_CUADRE CHECK (
        TOTAL_INCLUIDO = TOTAL_DEUDA AND TOTAL_CAPITAL_CUOTAS = TOTAL_DEUDA
        AND CUOTAS_REGISTRADAS = NUMERO_CUOTAS + 1)
        DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT CK_ACUERDO_ESTADO CHECK (ESTADO IN ('VIGENTE','CUMPLIDO','INCUMPLIDO','ANULADO')),
    CONSTRAINT CK_ACUERDO_MOTIVO CHECK (ESTADO IN ('VIGENTE','CUMPLIDO') OR MOTIVO_ESTADO IS NOT NULL),
    CONSTRAINT CK_ACUERDO_VERSION CHECK (VERSION >= 0)
);

-- Facturas vencidas que se refinancian dentro del acuerdo (P-10: VENCIDA -> EN_ACUERDO)
CREATE TABLE ACUERDO_FACTURA (
    ACUERDO_ID      NUMBER(19)    NOT NULL,
    FACTURA_ID      NUMBER(19)    NOT NULL,
    VALOR_INCLUIDO  NUMBER(14,2)  NOT NULL,
    CONSTRAINT PK_ACUERDO_FACTURA PRIMARY KEY (ACUERDO_ID, FACTURA_ID),
    CONSTRAINT FK_ACFAC_ACUERDO FOREIGN KEY (ACUERDO_ID) REFERENCES ACUERDO_PAGO (ID),
    CONSTRAINT FK_ACFAC_FACTURA FOREIGN KEY (FACTURA_ID) REFERENCES FACTURA (ID),
    CONSTRAINT CK_ACFAC_VALOR CHECK (VALOR_INCLUIDO > 0)
);

-- Cuota 0 = cuota inicial; cuotas 1..N mensuales
CREATE TABLE CUOTA_ACUERDO (
    ID                 NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    ACUERDO_ID         NUMBER(19)          NOT NULL,
    NUMERO_CUOTA       NUMBER(3)           NOT NULL,
    VALOR_CAPITAL      NUMBER(14,2)        NOT NULL,
    VALOR_INTERES      NUMBER(14,2)        DEFAULT 0 NOT NULL,
    VALOR_CUOTA        NUMBER(14,2)        NOT NULL,
    FECHA_VENCIMIENTO  DATE                NOT NULL,
    ESTADO             VARCHAR2(10 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    FECHA_PAGO         TIMESTAMP,
    VERSION            NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_CUOTA_ACUERDO PRIMARY KEY (ID),
    CONSTRAINT UK_CUOTA_NUMERO UNIQUE (ACUERDO_ID, NUMERO_CUOTA),
    CONSTRAINT UK_CUOTA_VENCIMIENTO UNIQUE (ACUERDO_ID, FECHA_VENCIMIENTO),
    CONSTRAINT FK_CUOTA_ACUERDO FOREIGN KEY (ACUERDO_ID) REFERENCES ACUERDO_PAGO (ID),
    CONSTRAINT CK_CUOTA_NUMERO CHECK (NUMERO_CUOTA BETWEEN 0 AND 24),
    CONSTRAINT CK_CUOTA_VALORES CHECK (
        VALOR_CAPITAL > 0 AND VALOR_INTERES >= 0 AND VALOR_CUOTA = VALOR_CAPITAL + VALOR_INTERES),
    CONSTRAINT CK_CUOTA_INICIAL CHECK (NUMERO_CUOTA > 0 OR VALOR_INTERES = 0),
    CONSTRAINT CK_CUOTA_FECHA CHECK (FECHA_VENCIMIENTO = TRUNC(FECHA_VENCIMIENTO)),
    CONSTRAINT CK_CUOTA_ESTADO CHECK (ESTADO IN ('PENDIENTE','PAGADA','VENCIDA')),
    CONSTRAINT CK_CUOTA_PAGADA CHECK (
        (ESTADO = 'PAGADA' AND FECHA_PAGO IS NOT NULL) OR (ESTADO <> 'PAGADA' AND FECHA_PAGO IS NULL)),
    CONSTRAINT CK_CUOTA_VERSION CHECK (VERSION >= 0)
);

-- Proceso de cobro persuasivo de un usuario moroso (CU-08, RN-03, RN-07, P-11, P-12)
CREATE TABLE COBRO_PERSUASIVO (
    ID                       NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    USUARIO_ID               NUMBER(19)          NOT NULL,
    FECHA_INICIO             DATE                NOT NULL,
    VALOR_DEUDA              NUMBER(14,2)        NOT NULL,
    PERIODOS_MORA            NUMBER(3)           NOT NULL,
    ESTADO                   VARCHAR2(12 CHAR)   DEFAULT 'ACTIVO' NOT NULL,
    ACUERDO_ID               NUMBER(19),
    CANDIDATO_SUSPENSION     CHAR(1)             DEFAULT 'N' NOT NULL,
    FECHA_AVISO_SUSPENSION   TIMESTAMP,
    FECHA_ESTADO             TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    OBSERVACION              VARCHAR2(500 CHAR),
    FUNCIONARIO_ID           NUMBER(19),
    VERSION                  NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_COBRO_PERSUASIVO PRIMARY KEY (ID),
    CONSTRAINT FK_COBRO_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT FK_COBRO_ACUERDO FOREIGN KEY (ACUERDO_ID) REFERENCES ACUERDO_PAGO (ID),
    CONSTRAINT FK_COBRO_FUNCIONARIO FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_COBRO_FECHA CHECK (FECHA_INICIO = TRUNC(FECHA_INICIO)),
    CONSTRAINT CK_COBRO_VALORES CHECK (VALOR_DEUDA > 0 AND PERIODOS_MORA >= 1),
    CONSTRAINT CK_COBRO_ESTADO CHECK (ESTADO IN ('ACTIVO','SUSPENDIDO','CERRADO')),
    -- RN-07: el cobro solo se suspende por un acuerdo de pago
    CONSTRAINT CK_COBRO_SUSPENSION CHECK (ESTADO <> 'SUSPENDIDO' OR ACUERDO_ID IS NOT NULL),
    -- RN-03: candidato a suspensión solo con cobro activo; el mínimo de periodos lo fija
    -- el parámetro MORA_PERIODOS_SUSPENSION (trigger). El aviso exige ser candidato.
    CONSTRAINT CK_COBRO_CANDIDATO CHECK (CANDIDATO_SUSPENSION = 'N' OR (CANDIDATO_SUSPENSION = 'S' AND ESTADO = 'ACTIVO')),
    CONSTRAINT CK_COBRO_AVISO CHECK (FECHA_AVISO_SUSPENSION IS NULL OR CANDIDATO_SUSPENSION = 'S'),
    CONSTRAINT CK_COBRO_VERSION CHECK (VERSION >= 0)
);

-- =====================================================================
-- 6. PAGOS (RF-06, F-04, SWR-05..08, RN-05, RN-13..15, RN-33, CO-02, P-05, P-18, P-23)
-- Un pago cubre UNA factura (todo su valor exigible) o UNA cuota de acuerdo.
-- =====================================================================

-- Cada intento contra la pasarela. SIGCA nunca recibe datos de tarjeta (P-18):
-- redirige a la pasarela y recibe la confirmación por webhook firmado con HMAC-SHA256.
CREATE TABLE TRANSACCION_PASARELA (
    ID                    NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    REFERENCIA            VARCHAR2(40 CHAR)   NOT NULL,
    REFERENCIA_PAGO       VARCHAR2(20 CHAR)   NOT NULL,
    FACTURA_ID            NUMBER(19),
    CUOTA_ID              NUMBER(19),
    USUARIO_ID            NUMBER(19)          NOT NULL,
    MONTO                 NUMBER(14,2)        NOT NULL,
    ESTADO                VARCHAR2(10 CHAR)   DEFAULT 'INICIADA' NOT NULL,
    CODIGO_TRANSACCION    VARCHAR2(60 CHAR),
    CODIGO_RESPUESTA      VARCHAR2(20 CHAR),
    MENSAJE_RESPUESTA     VARCHAR2(300 CHAR),
    FIRMA_VALIDADA        CHAR(1)             DEFAULT 'N' NOT NULL,
    INTENTOS              NUMBER(2)           DEFAULT 1 NOT NULL,
    IP_ORIGEN             VARCHAR2(45 CHAR),
    INICIADA_EN           TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    RESPONDIDA_EN         TIMESTAMP,
    VERSION               NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_TRANSACCION_PASARELA PRIMARY KEY (ID),
    CONSTRAINT UK_TRANSACCION_REFERENCIA UNIQUE (REFERENCIA),
    -- RN-15: el código de la pasarela es único (idempotencia del webhook)
    CONSTRAINT UK_TRANSACCION_CODIGO UNIQUE (CODIGO_TRANSACCION),
    CONSTRAINT FK_TRANSACCION_FACTURA FOREIGN KEY (FACTURA_ID) REFERENCES FACTURA (ID),
    CONSTRAINT FK_TRANSACCION_CUOTA FOREIGN KEY (CUOTA_ID) REFERENCES CUOTA_ACUERDO (ID),
    CONSTRAINT FK_TRANSACCION_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT CK_TRANSACCION_DESTINO CHECK (
        (FACTURA_ID IS NOT NULL AND CUOTA_ID IS NULL) OR (FACTURA_ID IS NULL AND CUOTA_ID IS NOT NULL)),
    CONSTRAINT CK_TRANSACCION_REFERENCIA CHECK (REGEXP_LIKE(REFERENCIA, '^[A-Za-z0-9-]{8,40}$')),
    -- P-18: referencia de pago = número de factura, o número de acuerdo + cuota
    CONSTRAINT CK_TRANSACCION_REF_PAGO CHECK (
        (FACTURA_ID IS NOT NULL AND REGEXP_LIKE(REFERENCIA_PAGO, '^FAC-[0-9]{6}-[0-9]{7}$'))
     OR (CUOTA_ID IS NOT NULL AND REGEXP_LIKE(REFERENCIA_PAGO, '^AP-[0-9]{4}-[0-9]{6}-[0-9]{2}$'))),
    CONSTRAINT CK_TRANSACCION_MONTO CHECK (MONTO > 0),
    CONSTRAINT CK_TRANSACCION_ESTADO CHECK (ESTADO IN ('INICIADA','APROBADA','RECHAZADA','ERROR','EXPIRADA')),
    -- CO-02: timeout 30 s y máximo 2 reintentos => hasta 3 intentos
    CONSTRAINT CK_TRANSACCION_INTENTOS CHECK (INTENTOS BETWEEN 1 AND 3),
    CONSTRAINT CK_TRANSACCION_FIRMA CHECK (
        FIRMA_VALIDADA IN ('S','N') AND (ESTADO NOT IN ('APROBADA','RECHAZADA') OR FIRMA_VALIDADA = 'S')),
    CONSTRAINT CK_TRANSACCION_RESPUESTA CHECK (ESTADO IN ('INICIADA','EXPIRADA') OR RESPONDIDA_EN IS NOT NULL),
    CONSTRAINT CK_TRANSACCION_APROBADA CHECK (ESTADO <> 'APROBADA' OR CODIGO_TRANSACCION IS NOT NULL),
    CONSTRAINT CK_TRANSACCION_RECHAZO CHECK (ESTADO <> 'RECHAZADA' OR CODIGO_RESPUESTA IS NOT NULL),
    CONSTRAINT CK_TRANSACCION_VERSION CHECK (VERSION >= 0)
);

CREATE TABLE PAGO (
    ID                       NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    CODIGO_PAGO              VARCHAR2(14 CHAR)   NOT NULL,
    USUARIO_ID               NUMBER(19)          NOT NULL,
    FACTURA_ID               NUMBER(19),
    CUOTA_ID                 NUMBER(19),
    FECHA_PAGO               TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    VALOR                    NUMBER(14,2)        NOT NULL,
    CANAL_PAGO               VARCHAR2(10 CHAR)   NOT NULL,
    TRANSACCION_PASARELA_ID  NUMBER(19),
    CODIGO_TRANSACCION       VARCHAR2(60 CHAR),
    REFERENCIA_BANCO         VARCHAR2(60 CHAR),
    FUNCIONARIO_ID           NUMBER(19),
    COMPROBANTE_ENVIADO      CHAR(1)             DEFAULT 'N' NOT NULL,
    ESTADO_SYNC_ERP          VARCHAR2(12 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    REFERENCIA_ERP           VARCHAR2(60 CHAR),
    FECHA_SYNC_ERP           TIMESTAMP,
    CREADO_EN                TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CREADO_POR               VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    CONSTRAINT PK_PAGO PRIMARY KEY (ID),
    CONSTRAINT UK_PAGO_CODIGO UNIQUE (CODIGO_PAGO),
    -- Una cuota recibe un solo pago. Una factura puede recibir más de uno solo cuando
    -- una línea en reclamo se paga después de resolverse (RN-33); el doble pago lo
    -- impide el trigger, que exige pagar exactamente el valor exigible vigente.
    CONSTRAINT UK_PAGO_CUOTA UNIQUE (CUOTA_ID),
    CONSTRAINT UK_PAGO_TRANSACCION UNIQUE (TRANSACCION_PASARELA_ID),
    CONSTRAINT UK_PAGO_CODIGO_TX UNIQUE (CODIGO_TRANSACCION),
    CONSTRAINT FK_PAGO_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT FK_PAGO_FACTURA FOREIGN KEY (FACTURA_ID) REFERENCES FACTURA (ID),
    CONSTRAINT FK_PAGO_CUOTA FOREIGN KEY (CUOTA_ID) REFERENCES CUOTA_ACUERDO (ID),
    CONSTRAINT FK_PAGO_TRANSACCION FOREIGN KEY (TRANSACCION_PASARELA_ID) REFERENCES TRANSACCION_PASARELA (ID),
    CONSTRAINT FK_PAGO_FUNCIONARIO FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_PAGO_CODIGO CHECK (REGEXP_LIKE(CODIGO_PAGO, '^PAG-[0-9]{10}$')),
    CONSTRAINT CK_PAGO_DESTINO CHECK (
        (FACTURA_ID IS NOT NULL AND CUOTA_ID IS NULL) OR (FACTURA_ID IS NULL AND CUOTA_ID IS NOT NULL)),
    CONSTRAINT CK_PAGO_VALOR CHECK (VALOR > 0),
    CONSTRAINT CK_PAGO_CANAL CHECK (CANAL_PAGO IN ('PRESENCIAL','EN_LINEA','BANCO')),
    -- Cada canal exige su evidencia: pasarela, funcionario o referencia bancaria (registrada por funcionario)
    CONSTRAINT CK_PAGO_CANAL_DATOS CHECK (
        (CANAL_PAGO = 'EN_LINEA'   AND TRANSACCION_PASARELA_ID IS NOT NULL AND CODIGO_TRANSACCION IS NOT NULL
                                   AND FUNCIONARIO_ID IS NULL AND REFERENCIA_BANCO IS NULL)
     OR (CANAL_PAGO = 'PRESENCIAL' AND FUNCIONARIO_ID IS NOT NULL AND REFERENCIA_BANCO IS NULL
                                   AND TRANSACCION_PASARELA_ID IS NULL AND CODIGO_TRANSACCION IS NULL)
     OR (CANAL_PAGO = 'BANCO'      AND FUNCIONARIO_ID IS NOT NULL AND REFERENCIA_BANCO IS NOT NULL
                                   AND TRANSACCION_PASARELA_ID IS NULL AND CODIGO_TRANSACCION IS NULL)),
    CONSTRAINT CK_PAGO_COMPROBANTE CHECK (COMPROBANTE_ENVIADO IN ('S','N')),
    CONSTRAINT CK_PAGO_SYNC CHECK (ESTADO_SYNC_ERP IN ('PENDIENTE','SINCRONIZADA','ERROR')),
    CONSTRAINT CK_PAGO_SYNC_REF CHECK (
        ESTADO_SYNC_ERP <> 'SINCRONIZADA' OR (REFERENCIA_ERP IS NOT NULL AND FECHA_SYNC_ERP IS NOT NULL))
);

ALTER TABLE LINEA_FACTURA ADD CONSTRAINT FK_LINEA_PAGO FOREIGN KEY (PAGO_ID) REFERENCES PAGO (ID);

-- Órdenes de suspensión y reconexión del servicio (P-11, P-12, RN-03, RN-36, Ley 142 arts. 140-142).
--   SUSPENSION por MORA: requiere cobro activo, candidato notificado y ningún acuerdo vigente.
--   RECONEXION por PAGO o ACUERDO: la genera el sistema; plazo máximo RECONEXION_HORAS (24 h)
--   y causa el cargo de reconexión. Ejecutar la orden cambia el estado del contrato.
CREATE TABLE ORDEN_SERVICIO (
    ID                 NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    NUMERO_ORDEN       VARCHAR2(12 CHAR)   NOT NULL,
    CONTRATO_ID        NUMBER(19)          NOT NULL,
    TIPO               VARCHAR2(12 CHAR)   NOT NULL,
    CAUSA              VARCHAR2(20 CHAR)   NOT NULL,
    COBRO_ID           NUMBER(19),
    PAGO_ID            NUMBER(19),
    ACUERDO_ID         NUMBER(19),
    FECHA_ORDEN        TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    FECHA_LIMITE       TIMESTAMP,
    VALOR_CARGO        NUMBER(14,2)        DEFAULT 0 NOT NULL,
    ESTADO             VARCHAR2(10 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    FECHA_EJECUCION    TIMESTAMP,
    EJECUTADA_POR      NUMBER(19),
    MOTIVO_ANULACION   VARCHAR2(300 CHAR),
    OBSERVACION        VARCHAR2(500 CHAR),
    CREADO_POR         VARCHAR2(100 CHAR)  DEFAULT 'SISTEMA' NOT NULL,
    VERSION            NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_ORDEN_SERVICIO PRIMARY KEY (ID),
    CONSTRAINT UK_ORDEN_NUMERO UNIQUE (NUMERO_ORDEN),
    CONSTRAINT FK_ORDEN_CONTRATO FOREIGN KEY (CONTRATO_ID) REFERENCES CONTRATO_SERVICIO (ID),
    CONSTRAINT FK_ORDEN_COBRO FOREIGN KEY (COBRO_ID) REFERENCES COBRO_PERSUASIVO (ID),
    CONSTRAINT FK_ORDEN_PAGO FOREIGN KEY (PAGO_ID) REFERENCES PAGO (ID),
    CONSTRAINT FK_ORDEN_ACUERDO FOREIGN KEY (ACUERDO_ID) REFERENCES ACUERDO_PAGO (ID),
    CONSTRAINT FK_ORDEN_EJECUTOR FOREIGN KEY (EJECUTADA_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_ORDEN_NUMERO CHECK (REGEXP_LIKE(NUMERO_ORDEN, '^OS-[0-9]{8}$')),
    CONSTRAINT CK_ORDEN_TIPO CHECK (TIPO IN ('SUSPENSION','RECONEXION')),
    CONSTRAINT CK_ORDEN_CAUSA CHECK (
        (TIPO = 'SUSPENSION' AND CAUSA IN ('MORA','SOLICITUD_USUARIO','TECNICA')
            AND PAGO_ID IS NULL AND ACUERDO_ID IS NULL AND VALOR_CARGO = 0
            AND ((CAUSA = 'MORA' AND COBRO_ID IS NOT NULL) OR (CAUSA <> 'MORA' AND COBRO_ID IS NULL)))
     OR (TIPO = 'RECONEXION' AND CAUSA IN ('PAGO','ACUERDO','SOLICITUD_USUARIO','TECNICA')
            AND COBRO_ID IS NULL AND FECHA_LIMITE IS NOT NULL
            AND ((CAUSA = 'PAGO' AND PAGO_ID IS NOT NULL AND ACUERDO_ID IS NULL)
              OR (CAUSA = 'ACUERDO' AND ACUERDO_ID IS NOT NULL AND PAGO_ID IS NULL)
              OR (CAUSA IN ('SOLICITUD_USUARIO','TECNICA') AND PAGO_ID IS NULL AND ACUERDO_ID IS NULL)))),
    CONSTRAINT CK_ORDEN_LIMITE CHECK (FECHA_LIMITE IS NULL OR FECHA_LIMITE > FECHA_ORDEN),
    CONSTRAINT CK_ORDEN_CARGO CHECK (VALOR_CARGO >= 0),
    CONSTRAINT CK_ORDEN_ESTADO CHECK (ESTADO IN ('PENDIENTE','EJECUTADA','ANULADA')),
    CONSTRAINT CK_ORDEN_EJECUCION CHECK (
        (ESTADO = 'PENDIENTE' AND FECHA_EJECUCION IS NULL AND EJECUTADA_POR IS NULL AND MOTIVO_ANULACION IS NULL)
     OR (ESTADO = 'EJECUTADA' AND FECHA_EJECUCION IS NOT NULL AND EJECUTADA_POR IS NOT NULL AND MOTIVO_ANULACION IS NULL)
     OR (ESTADO = 'ANULADA' AND FECHA_EJECUCION IS NULL AND MOTIVO_ANULACION IS NOT NULL
            AND LENGTH(TRIM(MOTIVO_ANULACION)) >= 5)),
    CONSTRAINT CK_ORDEN_VERSION CHECK (VERSION >= 0)
);

-- =====================================================================
-- 7. PQR (RF-08, RF-09, RF-10, F-05, F-06, CU-06, DE-02, RN-04, RN-06, CO-01,
--    P-03, P-14, P-15, RN-31, RN-32)
-- =====================================================================

-- Consecutivos que se reinician (P-27). El radicado usa el prefijo 'RAD-AAAAMM'.
CREATE TABLE CONSECUTIVO (
    PREFIJO  VARCHAR2(20 CHAR)  NOT NULL,
    ULTIMO   NUMBER(10)         DEFAULT 0 NOT NULL,
    MAXIMO   NUMBER(10)         NOT NULL,
    CONSTRAINT PK_CONSECUTIVO PRIMARY KEY (PREFIJO),
    CONSTRAINT CK_CONSECUTIVO_PREFIJO CHECK (REGEXP_LIKE(PREFIJO, '^[A-Z]{2,5}-[0-9A-Z]{1,14}$')),
    CONSTRAINT CK_CONSECUTIVO_VALORES CHECK (MAXIMO > 0 AND ULTIMO BETWEEN 0 AND MAXIMO)
);

-- Tipos: PETICION, QUEJA, RECLAMO y RECURSO; 15 días hábiles para todos (P-03).
--   * Una PETICION se puede radicar sin contrato con la identificación del solicitante (P-14);
--     QUEJA, RECLAMO y RECURSO exigen contrato.
--   * RECURSO: reposición (y en subsidio apelación) contra la respuesta de una PQR, dentro de
--     los 5 días hábiles siguientes (P-15, RN-32). Si EPQ confirma y se pidió apelación, pasa
--     a TRASLADADA_SSPD y se cierra cuando se registra la decisión de la Superintendencia.
--   * VENCIDA marca silencio administrativo positivo; EPQ lo reconoce en 72 h (RN-31).
--   * Un RECLAMO o RECURSO sobre una línea de factura suspende el cobro de esa línea (RN-33).
CREATE TABLE PQR (
    ID                                 NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    NUMERO_RADICADO                    VARCHAR2(11 CHAR)   NOT NULL,
    TIPO                               VARCHAR2(10 CHAR)   NOT NULL,
    CANAL                              VARCHAR2(10 CHAR)   DEFAULT 'PORTAL' NOT NULL,
    CONTRATO_ID                        NUMBER(19),
    USUARIO_ID                         NUMBER(19),
    MUNICIPIO_ID                       NUMBER(19)          NOT NULL,
    SOLICITANTE_TIPO_IDENTIFICACION    VARCHAR2(3 CHAR),
    SOLICITANTE_IDENTIFICACION_CIFRADO VARCHAR2(255 CHAR),
    SOLICITANTE_IDENTIFICACION_HASH    CHAR(64 CHAR),
    SOLICITANTE_IDENTIFICACION_MASCARA VARCHAR2(20 CHAR),
    PQR_ORIGEN_ID                      NUMBER(19),
    SOLICITA_APELACION                 CHAR(1)             DEFAULT 'N' NOT NULL,
    LINEA_FACTURA_ID                   NUMBER(19),
    DESCRIPCION                        CLOB                NOT NULL,
    NOMBRE_CONTACTO                    VARCHAR2(150 CHAR)  NOT NULL,
    CORREO_CONTACTO                    VARCHAR2(254 CHAR)  NOT NULL,
    TELEFONO_CONTACTO                  VARCHAR2(13 CHAR)   NOT NULL,
    FECHA_REGISTRO                     TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    FECHA_LIMITE_RESPUESTA             DATE                NOT NULL,
    ESTADO                             VARCHAR2(15 CHAR)   DEFAULT 'RECIBIDA' NOT NULL,
    FECHA_ESTADO                       TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    GESTOR_ID                          NUMBER(19)          NOT NULL,
    FECHA_ASIGNACION                   TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    FECHA_INICIO_TRAMITE               TIMESTAMP,
    RESPUESTA                          CLOB,
    FECHA_RESPUESTA                    TIMESTAMP,
    RESPONDIDA_POR                     NUMBER(19),
    RESPUESTA_EXTEMPORANEA             CHAR(1)             DEFAULT 'N' NOT NULL,
    DECISION_RECURSO                   VARCHAR2(10 CHAR),
    FECHA_TRASLADO_SSPD                TIMESTAMP,
    DECISION_SSPD                      VARCHAR2(10 CHAR),
    FECHA_DECISION_SSPD                TIMESTAMP,
    SILENCIO_POSITIVO                  CHAR(1)             DEFAULT 'N' NOT NULL,
    FECHA_LIMITE_RECONOCIMIENTO        TIMESTAMP,
    FECHA_RECONOCIMIENTO_SILENCIO      TIMESTAMP,
    ALERTA_48H_ENVIADA                 CHAR(1)             DEFAULT 'N' NOT NULL,
    REPORTADA_SSPD                     CHAR(1)             DEFAULT 'N' NOT NULL,
    REGISTRADA_POR                     NUMBER(19),
    CREADO_EN                          TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    ACTUALIZADO_EN                     TIMESTAMP,
    ACTUALIZADO_POR                    VARCHAR2(100 CHAR),
    VERSION                            NUMBER(10)          DEFAULT 0 NOT NULL,
    CONSTRAINT PK_PQR PRIMARY KEY (ID),
    CONSTRAINT UK_PQR_RADICADO UNIQUE (NUMERO_RADICADO),
    -- Un solo recurso por PQR respondida
    CONSTRAINT UK_PQR_ORIGEN UNIQUE (PQR_ORIGEN_ID),
    CONSTRAINT FK_PQR_CONTRATO FOREIGN KEY (CONTRATO_ID) REFERENCES CONTRATO_SERVICIO (ID),
    CONSTRAINT FK_PQR_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT FK_PQR_MUNICIPIO FOREIGN KEY (MUNICIPIO_ID) REFERENCES MUNICIPIO (ID),
    CONSTRAINT FK_PQR_ORIGEN FOREIGN KEY (PQR_ORIGEN_ID) REFERENCES PQR (ID),
    CONSTRAINT FK_PQR_LINEA FOREIGN KEY (LINEA_FACTURA_ID) REFERENCES LINEA_FACTURA (ID),
    CONSTRAINT FK_PQR_GESTOR FOREIGN KEY (GESTOR_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT FK_PQR_RESPONDIDA_POR FOREIGN KEY (RESPONDIDA_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT FK_PQR_REGISTRADA_POR FOREIGN KEY (REGISTRADA_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_PQR_RADICADO CHECK (REGEXP_LIKE(NUMERO_RADICADO, '^[0-9]{4}(0[1-9]|1[0-2])-[0-9]{4}$')),
    CONSTRAINT CK_PQR_TIPO CHECK (TIPO IN ('PETICION','QUEJA','RECLAMO','RECURSO')),
    -- Portal: lo radica el ciudadano; presencial: lo radica un funcionario
    CONSTRAINT CK_PQR_CANAL CHECK (
        (CANAL = 'PORTAL' AND REGISTRADA_POR IS NULL) OR (CANAL = 'PRESENCIAL' AND REGISTRADA_POR IS NOT NULL)),
    -- P-14: con contrato, el titular lo da el contrato; sin contrato, solo PETICION con la identificación del solicitante
    CONSTRAINT CK_PQR_SOLICITANTE CHECK (
        (CONTRATO_ID IS NOT NULL AND USUARIO_ID IS NOT NULL
            AND SOLICITANTE_TIPO_IDENTIFICACION IS NULL AND SOLICITANTE_IDENTIFICACION_CIFRADO IS NULL
            AND SOLICITANTE_IDENTIFICACION_HASH IS NULL AND SOLICITANTE_IDENTIFICACION_MASCARA IS NULL)
     OR (CONTRATO_ID IS NULL AND USUARIO_ID IS NULL AND TIPO = 'PETICION'
            AND SOLICITANTE_TIPO_IDENTIFICACION IS NOT NULL AND SOLICITANTE_IDENTIFICACION_CIFRADO IS NOT NULL
            AND SOLICITANTE_IDENTIFICACION_HASH IS NOT NULL AND SOLICITANTE_IDENTIFICACION_MASCARA IS NOT NULL
            AND SOLICITANTE_TIPO_IDENTIFICACION IN ('CC','CE','TI','PA','PPT','NIT')
            AND REGEXP_LIKE(SOLICITANTE_IDENTIFICACION_CIFRADO, '^[A-Za-z0-9+/]{20,}={0,2}$')
            AND REGEXP_LIKE(SOLICITANTE_IDENTIFICACION_HASH, '^[0-9a-f]{64}$')
            AND REGEXP_LIKE(SOLICITANTE_IDENTIFICACION_MASCARA, '^\*+[A-Z0-9-]{1,4}$'))),
    -- P-15: el recurso se vincula a la PQR original; la apelación solo se pide en un recurso
    CONSTRAINT CK_PQR_RECURSO CHECK (
        (TIPO = 'RECURSO' AND PQR_ORIGEN_ID IS NOT NULL AND SOLICITA_APELACION IN ('S','N'))
     OR (TIPO <> 'RECURSO' AND PQR_ORIGEN_ID IS NULL AND SOLICITA_APELACION = 'N')),
    CONSTRAINT CK_PQR_LINEA CHECK (LINEA_FACTURA_ID IS NULL OR TIPO IN ('RECLAMO','RECURSO')),
    -- 20 a 4000 caracteres; el backend recorta y elimina HTML antes de guardar (XSS)
    CONSTRAINT CK_PQR_DESCRIPCION CHECK (LENGTH(TRIM(DESCRIPCION)) BETWEEN 20 AND 4000),
    CONSTRAINT CK_PQR_NOMBRE CHECK (REGEXP_LIKE(TRIM(NOMBRE_CONTACTO), '^[[:alpha:]][[:alpha:] .''-]{2,149}$')),
    CONSTRAINT CK_PQR_CORREO CHECK (
        CORREO_CONTACTO = LOWER(TRIM(CORREO_CONTACTO))
        AND REGEXP_LIKE(CORREO_CONTACTO, '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$')),
    CONSTRAINT CK_PQR_TELEFONO CHECK (REGEXP_LIKE(TELEFONO_CONTACTO, '^(\+57)?(3[0-9]{9}|60[0-9]{8})$')),
    CONSTRAINT CK_PQR_FECHA_LIMITE CHECK (FECHA_LIMITE_RESPUESTA = TRUNC(FECHA_LIMITE_RESPUESTA)),
    CONSTRAINT CK_PQR_ESTADO CHECK (ESTADO IN ('RECIBIDA','EN_TRAMITE','RESPONDIDA','VENCIDA','TRASLADADA_SSPD')),
    CONSTRAINT CK_PQR_TRAMITE CHECK (ESTADO <> 'EN_TRAMITE' OR FECHA_INICIO_TRAMITE IS NOT NULL),
    -- RN-06: la respuesta formal de EPQ existe en RESPONDIDA y en TRASLADADA_SSPD
    CONSTRAINT CK_PQR_RESPUESTA CHECK (
        (ESTADO IN ('RESPONDIDA','TRASLADADA_SSPD') AND RESPUESTA IS NOT NULL
                               AND LENGTH(TRIM(RESPUESTA)) BETWEEN 20 AND 4000
                               AND FECHA_RESPUESTA IS NOT NULL AND RESPONDIDA_POR IS NOT NULL)
     OR (ESTADO NOT IN ('RESPONDIDA','TRASLADADA_SSPD') AND FECHA_RESPUESTA IS NULL AND RESPONDIDA_POR IS NULL)),
    CONSTRAINT CK_PQR_DECISION CHECK (
        (DECISION_RECURSO IS NULL OR (TIPO = 'RECURSO' AND DECISION_RECURSO IN ('CONFIRMA','REVOCA','MODIFICA')))
        AND (TIPO <> 'RECURSO' OR ESTADO NOT IN ('RESPONDIDA','TRASLADADA_SSPD') OR DECISION_RECURSO IS NOT NULL)),
    -- Solo un recurso con apelación y decisión confirmada llega a la SSPD
    CONSTRAINT CK_PQR_TRASLADO CHECK (
        (FECHA_TRASLADO_SSPD IS NULL AND DECISION_SSPD IS NULL AND FECHA_DECISION_SSPD IS NULL
            AND ESTADO <> 'TRASLADADA_SSPD')
     OR (FECHA_TRASLADO_SSPD IS NOT NULL AND TIPO = 'RECURSO' AND SOLICITA_APELACION = 'S'
            AND DECISION_RECURSO IS NOT NULL AND DECISION_RECURSO = 'CONFIRMA'
            AND ((ESTADO = 'TRASLADADA_SSPD' AND DECISION_SSPD IS NULL AND FECHA_DECISION_SSPD IS NULL)
              OR (ESTADO = 'RESPONDIDA' AND DECISION_SSPD IS NOT NULL
                  AND DECISION_SSPD IN ('CONFIRMA','REVOCA','MODIFICA')
                  AND FECHA_DECISION_SSPD IS NOT NULL)))),
    -- RN-31: silencio administrativo positivo con plazo de reconocimiento
    CONSTRAINT CK_PQR_SILENCIO CHECK (
        (SILENCIO_POSITIVO = 'N' AND FECHA_LIMITE_RECONOCIMIENTO IS NULL AND FECHA_RECONOCIMIENTO_SILENCIO IS NULL)
     OR (SILENCIO_POSITIVO = 'S' AND FECHA_LIMITE_RECONOCIMIENTO IS NOT NULL)),
    CONSTRAINT CK_PQR_FLAGS CHECK (
        RESPUESTA_EXTEMPORANEA IN ('S','N') AND ALERTA_48H_ENVIADA IN ('S','N') AND REPORTADA_SSPD IN ('S','N')),
    CONSTRAINT CK_PQR_VERSION CHECK (VERSION >= 0)
);

-- Trazabilidad de cambios de estado y reasignaciones (RF-09); la llena el trigger
CREATE TABLE PQR_HISTORIAL (
    ID                NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    PQR_ID            NUMBER(19)          NOT NULL,
    ESTADO_ANTERIOR   VARCHAR2(15 CHAR),
    ESTADO_NUEVO      VARCHAR2(15 CHAR)   NOT NULL,
    GESTOR_ANTERIOR   NUMBER(19),
    GESTOR_NUEVO      NUMBER(19),
    FECHA             TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    REALIZADO_POR     VARCHAR2(100 CHAR)  NOT NULL,
    CONSTRAINT PK_PQR_HISTORIAL PRIMARY KEY (ID),
    CONSTRAINT FK_PQRHIST_PQR FOREIGN KEY (PQR_ID) REFERENCES PQR (ID),
    CONSTRAINT FK_PQRHIST_GESTOR_ANT FOREIGN KEY (GESTOR_ANTERIOR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT FK_PQRHIST_GESTOR_NUE FOREIGN KEY (GESTOR_NUEVO) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_PQRHIST_ESTADOS CHECK (
        (ESTADO_ANTERIOR IS NULL OR ESTADO_ANTERIOR IN ('RECIBIDA','EN_TRAMITE','RESPONDIDA','VENCIDA','TRASLADADA_SSPD'))
        AND ESTADO_NUEVO IN ('RECIBIDA','EN_TRAMITE','RESPONDIDA','VENCIDA','TRASLADADA_SSPD'))
);

-- Acciones documentadas por el gestor durante el trámite (CU-06 paso 8)
CREATE TABLE PQR_ACTUACION (
    ID              NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    PQR_ID          NUMBER(19)          NOT NULL,
    FUNCIONARIO_ID  NUMBER(19)          NOT NULL,
    FECHA           TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    DESCRIPCION     VARCHAR2(2000 CHAR) NOT NULL,
    CONSTRAINT PK_PQR_ACTUACION PRIMARY KEY (ID),
    CONSTRAINT FK_PQRACT_PQR FOREIGN KEY (PQR_ID) REFERENCES PQR (ID),
    CONSTRAINT FK_PQRACT_FUNCIONARIO FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_PQRACT_DESCRIPCION CHECK (LENGTH(TRIM(DESCRIPCION)) BETWEEN 5 AND 2000)
);

-- Documentos de soporte del ciudadano y evidencias de respuesta (RN-06, SWR-20)
CREATE TABLE PQR_ADJUNTO (
    ID               NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    PQR_ID           NUMBER(19)          NOT NULL,
    TIPO             VARCHAR2(12 CHAR)   NOT NULL,
    NOMBRE_ARCHIVO   VARCHAR2(200 CHAR)  NOT NULL,
    TIPO_MIME        VARCHAR2(100 CHAR)  NOT NULL,
    TAMANO_BYTES     NUMBER(10)          NOT NULL,
    HASH_SHA256      CHAR(64)            NOT NULL,
    CONTENIDO        BLOB                NOT NULL,
    CARGADO_POR      NUMBER(19),
    CARGADO_EN       TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_PQR_ADJUNTO PRIMARY KEY (ID),
    CONSTRAINT UK_PQRADJ_HASH UNIQUE (PQR_ID, HASH_SHA256),
    CONSTRAINT FK_PQRADJ_PQR FOREIGN KEY (PQR_ID) REFERENCES PQR (ID),
    CONSTRAINT FK_PQRADJ_FUNCIONARIO FOREIGN KEY (CARGADO_POR) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT CK_PQRADJ_TIPO CHECK (TIPO IN ('SOPORTE','EVIDENCIA')),
    -- Las evidencias de respuesta las carga siempre un funcionario
    CONSTRAINT CK_PQRADJ_EVIDENCIA CHECK (TIPO <> 'EVIDENCIA' OR CARGADO_POR IS NOT NULL),
    CONSTRAINT CK_PQRADJ_NOMBRE CHECK (REGEXP_LIKE(NOMBRE_ARCHIVO, '^[^/\\:*?"<>|]{1,200}$')),
    CONSTRAINT CK_PQRADJ_MIME CHECK (TIPO_MIME IN ('application/pdf','image/jpeg','image/png')),
    CONSTRAINT CK_PQRADJ_TAMANO CHECK (TAMANO_BYTES BETWEEN 1 AND 10485760),
    CONSTRAINT CK_PQRADJ_HASH CHECK (REGEXP_LIKE(HASH_SHA256, '^[0-9a-f]{64}$'))
)
LOB (CONTENIDO) STORE AS SECUREFILE (ENABLE STORAGE IN ROW);

-- =====================================================================
-- 8. TRANSVERSALES: NOTIFICACIONES Y AUDITORÍA (IS-SIS-02, RF-15)
-- =====================================================================

-- Bandeja de salida: se reintenta en segundo plano si el envío falla (CO-01). SMS simulado (P-25).
CREATE TABLE NOTIFICACION (
    ID                NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    EVENTO            VARCHAR2(30 CHAR)   NOT NULL,
    CANAL             VARCHAR2(8 CHAR)    NOT NULL,
    DESTINATARIO      VARCHAR2(254 CHAR),
    FUNCIONARIO_ID    NUMBER(19),
    USUARIO_ID        NUMBER(19),
    ASUNTO            VARCHAR2(200 CHAR),
    CUERPO            CLOB                NOT NULL,
    ENTIDAD           VARCHAR2(30 CHAR),
    ENTIDAD_ID        NUMBER(19),
    ESTADO            VARCHAR2(10 CHAR)   DEFAULT 'PENDIENTE' NOT NULL,
    INTENTOS          NUMBER(2)           DEFAULT 0 NOT NULL,
    PROXIMO_INTENTO   TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    ULTIMO_ERROR      VARCHAR2(500 CHAR),
    ENVIADA_EN        TIMESTAMP,
    LEIDA             CHAR(1)             DEFAULT 'N' NOT NULL,
    CREADO_EN         TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_NOTIFICACION PRIMARY KEY (ID),
    CONSTRAINT FK_NOTIF_FUNCIONARIO FOREIGN KEY (FUNCIONARIO_ID) REFERENCES FUNCIONARIO (ID),
    CONSTRAINT FK_NOTIF_USUARIO FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO (ID),
    CONSTRAINT CK_NOTIF_EVENTO CHECK (EVENTO IN (
        'PQR_RADICADA','PQR_ASIGNADA','PQR_ALERTA_48H','PQR_VENCIDA','PQR_RESPONDIDA',
        'PQR_SILENCIO_POSITIVO','PQR_ALERTA_RECONOCIMIENTO','PQR_TRASLADADA_SSPD',
        'LECTURA_EN_REVISION','FACTURA_EMITIDA','FACTURA_VENCIDA','FACTURA_REEXPEDIDA','COMPROBANTE_PAGO',
        'ACUERDO_CREADO','CUOTA_VENCIDA','ACUERDO_INCUMPLIDO','AVISO_SUSPENSION',
        'ORDEN_SUSPENSION','ORDEN_RECONEXION','RECONEXION_VENCIDA',
        'CUENTA_BLOQUEADA','GENERAL')),
    CONSTRAINT CK_NOTIF_CANAL CHECK (CANAL IN ('EMAIL','SMS','SISTEMA')),
    CONSTRAINT CK_NOTIF_DESTINO CHECK (
        (CANAL = 'SISTEMA' AND FUNCIONARIO_ID IS NOT NULL)
     OR (CANAL = 'EMAIL' AND DESTINATARIO IS NOT NULL AND REGEXP_LIKE(DESTINATARIO, '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'))
     OR (CANAL = 'SMS' AND DESTINATARIO IS NOT NULL AND REGEXP_LIKE(DESTINATARIO, '^(\+57)?3[0-9]{9}$'))),
    CONSTRAINT CK_NOTIF_ASUNTO CHECK (CANAL <> 'EMAIL' OR ASUNTO IS NOT NULL),
    CONSTRAINT CK_NOTIF_ESTADO CHECK (ESTADO IN ('PENDIENTE','ENVIADA','FALLIDA')),
    CONSTRAINT CK_NOTIF_ENVIADA CHECK (ESTADO <> 'ENVIADA' OR ENVIADA_EN IS NOT NULL),
    CONSTRAINT CK_NOTIF_INTENTOS CHECK (INTENTOS BETWEEN 0 AND 10),
    CONSTRAINT CK_NOTIF_LEIDA CHECK (LEIDA IN ('S','N'))
);

-- Log de auditoría inmutable (RF-15, RNF-05). Solo admite INSERT (ver trigger).
CREATE TABLE LOG_AUDITORIA (
    ID              NUMBER(19)          GENERATED ALWAYS AS IDENTITY,
    FECHA           TIMESTAMP           DEFAULT SYSTIMESTAMP NOT NULL,
    ACTOR_TIPO      VARCHAR2(12 CHAR)   NOT NULL,
    FUNCIONARIO_ID  NUMBER(19),
    USUARIO_ID      NUMBER(19),
    OPERACION       VARCHAR2(40 CHAR)   NOT NULL,
    ENTIDAD         VARCHAR2(30 CHAR),
    ENTIDAD_ID      NUMBER(19),
    RESULTADO       VARCHAR2(8 CHAR)    DEFAULT 'EXITO' NOT NULL,
    DETALLE         CLOB,
    IP_ORIGEN       VARCHAR2(45 CHAR),
    CONSTRAINT PK_LOG_AUDITORIA PRIMARY KEY (ID),
    -- Sin FK a FUNCIONARIO/USUARIO a propósito: el log no debe impedir ni depender de borrados
    CONSTRAINT CK_LOG_ACTOR CHECK (
        (ACTOR_TIPO = 'FUNCIONARIO' AND FUNCIONARIO_ID IS NOT NULL)
     OR (ACTOR_TIPO = 'CIUDADANO' AND USUARIO_ID IS NOT NULL)
     OR (ACTOR_TIPO = 'SISTEMA')
     OR (ACTOR_TIPO = 'ANONIMO')),
    CONSTRAINT CK_LOG_OPERACION CHECK (OPERACION IN (
        'INICIO_SESION','CIERRE_SESION','INICIO_SESION_FALLIDO','BLOQUEO_CUENTA','ENROLAR_2FA',
        'ACTIVAR_CUENTA_PORTAL','RECUPERAR_PASSWORD','CAMBIAR_PASSWORD',
        'CREAR_USUARIO','MODIFICAR_USUARIO','ACTUALIZAR_CONTACTO','INACTIVAR_USUARIO','VERIFICAR_RNEC',
        'CREAR_PREDIO','MODIFICAR_PREDIO','CREAR_MEDIDOR','RETIRAR_MEDIDOR',
        'REGISTRAR_LECTURA','CARGAR_LECTURAS','REVISAR_LECTURA','ESTIMAR_LECTURA',
        'CREAR_TARIFA','MODIFICAR_TARIFA','CREAR_FACTOR_SUBSIDIO','MODIFICAR_FACTOR_SUBSIDIO',
        'CREAR_CONTRATO','MODIFICAR_CONTRATO','CANCELAR_CONTRATO',
        'GENERAR_LOTE_FACTURAS','GENERAR_FACTURA','ANULAR_FACTURA','REEXPEDIR_FACTURA','AJUSTAR_LINEA',
        'SINCRONIZAR_ERP','VENCER_FACTURA','REGISTRAR_PAGO','PAGO_RECHAZADO',
        'INICIAR_COBRO','MARCAR_CANDIDATO_SUSPENSION','AVISAR_SUSPENSION','EXPORTAR_REPORTE',
        'ORDENAR_SUSPENSION','ORDENAR_RECONEXION','EJECUTAR_ORDEN','ANULAR_ORDEN',
        'CREAR_ACUERDO','INCUMPLIR_ACUERDO','CUMPLIR_ACUERDO','ANULAR_ACUERDO',
        'REGISTRAR_PQR','REGISTRAR_RECURSO','TOMAR_PQR','REASIGNAR_PQR','RESPONDER_PQR','VENCER_PQR',
        'RECONOCER_SILENCIO','TRASLADAR_SSPD','REGISTRAR_DECISION_SSPD',
        'CREAR_FUNCIONARIO','MODIFICAR_FUNCIONARIO','DESACTIVAR_FUNCIONARIO',
        'ASIGNAR_ROL','REVOCAR_ROL','MODIFICAR_PERMISOS','MODIFICAR_PARAMETRO','MODIFICAR_FESTIVOS',
        'MODIFICAR_MUNICIPIO','CREAR_SECTOR','MODIFICAR_SECTOR')),
    CONSTRAINT CK_LOG_RESULTADO CHECK (RESULTADO IN ('EXITO','FALLO')),
    CONSTRAINT CK_LOG_DETALLE_JSON CHECK (DETALLE IS JSON)
);
